// How many plays the table showed when last drawn, and how many it has, so
// the wheel scrolls no further than its end. The drawing clamps it again.
let lastRoom = 10
let lastCount = 0
let lastPictureMs = 0
// Whether a terminal has drawn the pane, so a move seen only on the other
// surfaces skips the RGBA picture they would not show.
let isTerminalDrawing = false

// What the mod did, newest last, for `/magpie why`.
const log: string[] = []
const LOG_KEPT = 40

function note(line: string) {
  log.push(`${new Date().toTimeString().slice(0, 8)} ${line}`)
  if (log.length > LOG_KEPT) {
    log.shift()
  }
}

let fontLoad: Promise<Font> | null = null

// Reads and parses the font once per load of the module; a failed read is
// tried again at the next draw.
export function loadFont($: EngineInterface): Promise<Font> {
  fontLoad ??= $.fs
    .read(`${$.plugin.root}/${FONT_FILE}`, { as: 'bytes' })
    .then(({ base64 }) => parseFont(Uint8Array.fromBase64(base64)))
    .catch((error: unknown) => {
      fontLoad = null
      throw error
    })
  return fontLoad
}

// Pictures by play id, for the sim loaded now: compressed, many fit, the
// listed plays' and those a sort or scroll reaches.
const pictures = new Map<string, string>()
const PICTURES_KEPT = 64
// Between two pictures drawn ahead, so the pane's events run between them.
const DRAW_AHEAD_MS = 15

// The last sim parsed, by what it was parsed from: a run's output, or a file.
let simLoad: { source: string; sim: Promise<Sim> } | null = null

async function simPath($: EngineInterface): Promise<string> {
  const file = await read($, simFile)
  return file === '' ? `${$.plugin.root}/${DEFAULT_SIM_FILE}` : file
}

// The position the pictures kept are of: they hold while a sim streams in
// and only its numbers change, and go when the board or rack does.
let picturesOf = ''

// The sim the pane shows: the last run's, else the file the show tool named,
// else the one the mod ships. Parsed once each; a failed read is tried again
// at the next draw.
export async function loadSim($: EngineInterface): Promise<Sim> {
  const text = await read($, simText)
  const source = text !== '' ? text : await simPath($)
  if (simLoad?.source !== source) {
    const parsed = text !== '' ? Promise.resolve().then(() => parseSim(text)) : $.fs.read(source).then(parseSim)
    const sim = parsed.then(async loaded => {
      // Its tiles drawn with their own set's scores.
      setTileScores(await scoresFor($, loaded.lexicon).catch(() => TILE_SCORES))
      const position = `${loaded.lexicon}|${loaded.rack}|${(loaded.board ?? []).join('/')}`
      if (position !== picturesOf) {
        pictures.clear()
        columnPictures.clear()
        drawingAhead = null
        picturesOf = position
      }
      return loaded
    })
    simLoad = { source, sim }
    sim.catch(() => {
      if (simLoad?.sim === sim) {
        simLoad = null
      }
    })
  }
  return simLoad.sim
}

let threadCount: Promise<number> | null = null

// All the cores but two, for the sim's threads: Windows names its count,
// getconf counts them elsewhere.
function threads($: EngineInterface): Promise<number> {
  threadCount ??= (async () => {
    const named = await $.env.get('NUMBER_OF_PROCESSORS')
    const cores = named ?? (await $.process.run(['getconf', '_NPROCESSORS_ONLN'])).stdout
    return Math.max(1, (Number.parseInt(cores, 10) || 6) - 2)
  })().catch(() => 4)
  return threadCount
}

let home: Promise<string> | null = null

async function expandHome($: EngineInterface, path: string): Promise<string> {
  if (path !== '~' && !/^~[\\/]/.test(path)) {
    return path
  }
  home ??= homeOf($)
  return (await home) + path.slice(1)
}

let host: Promise<Host> | null = null

// The computer the session runs on, read once.
function hostNow($: EngineInterface): Promise<Host> {
  host ??= hostOf($)
  return host
}

// An absolute path, `~` expanded and a relative one taken from the session's
// directory; rejects when nothing is there.
async function absolutePath($: EngineInterface, path: string): Promise<string> {
  const expanded = await expandHome($, path)
  const { realPath } = await $.fs.stat(expanded, { resolve: true })
  return realPath ?? expanded
}

// The lexicon a GCG names, when its text is at hand.
function gcgLexicon(text: string): string | undefined {
  return /^#lexicon\s+(\S+)/m.exec(text)?.[1]?.toUpperCase()
}

// The MAGPIE install that runs the sims, holding bin/magpie and data/: the
// magpieDir option, read as the module loads. Empty is the folder the mod
// installs MAGPIE in (setup.ts, defaultMagpieDir).
let magpieDir = ''

type Magpie = { binary: string; cwd?: string }

async function findMagpie($: EngineInterface): Promise<Magpie> {
  const machine = await hostNow($)
  const dir = magpieDir === '' ? await defaultMagpieDir($, machine) : await expandHome($, magpieDir)
  return { binary: executableIn(dir, machine), cwd: dir }
}

// Whichever of the RIT and WIT the lexicon has built. A lexicon or data
// directory not known before the run (a GCG MAGPIE fetches, the magpie on
// PATH) tries both, and the run goes again without them if MAGPIE finds them
// missing.
async function accelerators($: EngineInterface, magpie: Magpie, lexicon: string | undefined): Promise<Accelerators> {
  if (lexicon === undefined || magpie.cwd === undefined) {
    return { rit: true, wit: true }
  }
  const magpieDir = magpie.cwd
  const [rit, wit] = await Promise.all(
    ['rit', 'wit'].map(kind => $.fs.exists(`${magpieDir}/data/lexica/${lexicon}.${kind}`)),
  )
  return { rit: rit === true, wit: wit === true }
}

// The request with its position in MAGPIE's terms (Resolved), the moves
// played after it and its rack carried over.
async function resolveRequest($: EngineInterface, request: SimRequest): Promise<{ resolved: Resolved; lexicon?: string }> {
  const found = await resolvePosition($, request)
  const { after, rack } = request.position
  return {
    ...found,
    resolved: {
      ...found.resolved,
      ...(after === undefined || after.length === 0 ? {} : { after }),
      ...(rack === undefined || rack === '' || found.resolved.kind === 'rack' ? {} : { rack }),
    },
  }
}

// The position itself: a URL or file read and told apart, a local path made
// absolute for MAGPIE's own directory.
async function resolvePosition($: EngineInterface, request: SimRequest): Promise<{ resolved: Resolved; lexicon?: string }> {
  const position = request.position
  let lexicon = request.lexicon
  if (position.kind === 'rack' || position.kind === 'cgp') {
    return { resolved: position, lexicon }
  }
  if (position.kind === 'gcg') {
    if (/^https?:\/\//i.test(position.source) || !/[/.~]/.test(position.source)) {
      return { resolved: position, lexicon }
    }
    const path = await absolutePath($, position.source)
    lexicon ??= gcgLexicon(await $.fs.read(path))
    return { resolved: { kind: 'gcg' as const, source: path }, lexicon }
  }
  if (position.kind === 'url') {
    const fetched = await $.http.fetch(position.url).catch((error: unknown) => {
      throw new Error(`could not fetch ${position.url}: ${error instanceof Error ? error.message : String(error)}`)
    })
    if (!fetched.ok) {
      throw new Error(`could not fetch ${position.url}: HTTP ${fetched.status}`)
    }
    return sniffPosition(fetched.text) === 'cgp'
      ? { resolved: { kind: 'cgp' as const, cgp: fetched.text.trim() }, lexicon }
      : { resolved: { kind: 'gcg' as const, source: position.url }, lexicon: lexicon ?? gcgLexicon(fetched.text) }
  }
  const path = await absolutePath($, position.path)
  const text = await $.fs.read(path)
  return sniffPosition(text) === 'cgp'
    ? { resolved: { kind: 'cgp' as const, cgp: text.trim().split('\n')[0] ?? '' }, lexicon }
    : { resolved: { kind: 'gcg' as const, source: path }, lexicon: lexicon ?? gcgLexicon(text) }
}

// What MAGPIE said went wrong, when the run printed no sim.
function magpieErrors(stdout: string, stderr: string, otherwise: string): string {
  const lines = `${stderr}\n${stdout}`
    .split('\n')
    .map(line => line.trim())
    .filter(line => /error|fatal|not found|invalid|cannot/i.test(line))
  return lines.slice(0, 4).join('; ') || stderr.trim().slice(0, 300) || otherwise
}


/** A sim ready to run: the position in MAGPIE's terms, and for a GCG the
 * `goto` that reaches it. */
type Plan = {
  request: SimRequest
  resolved: Resolved
  lexicon?: string
  goto?: string
  label: string
  where: Magpie
  threadCount: number
  /** For a game: the turn chosen, and how many it has. */
  turn?: number
  turns?: number
  /** Simmed, or its endgame solved (the bag empty). */
  mode: Mode
}

/** What the pane says while a plan runs. */
function planStatus(plan: Plan): string {
  return plan.mode === 'endgame'
    ? `Solving the endgame of ${plan.label} in ${lexiconText(plan)}`
    : `Simulating ${plan.label} in ${lexiconText(plan)}: ${SIM_SHAPE}`
}

/** Which lexicon a plan runs in, as the person is told it. */
function lexiconText(plan: Plan): string {
  return runLexicon(plan.resolved, plan.lexicon) ?? "the game's lexicon"
}

/** What the pane shows, for `/magpie next turn` and `/magpie csw`: the
 * request that made it (a game's at its turn), its lexicon, and the game's
 * turn and turns. Kept as JSON in the `current` atom. */
type Current = { request: SimRequest; label: string; lexicon: string; turn?: number; turns?: number }

async function readCurrent($: EngineInterface): Promise<Current | undefined> {
  const json = await read($, current)
  return json === '' ? undefined : (JSON.parse(json) as Current)
}

const couldNotRun = (where: Magpie, error: unknown) =>
  new Error(
    `could not run ${where.binary} (${error instanceof Error ? error.message : String(error)}); install MAGPIE there, or set the mod's MAGPIE directory with \`claude plugin configure magpie-sim@olaugh-mods\``,
  )

// What MAGPIE printed as the mod reads it: a Windows one's CRLFs as LFs,
// bracketed tiles packed (tiles.ts).
const fromMagpie = (text: string) => packTiles(text.replaceAll('\r\n', '\n'))

async function execute($: EngineInterface, where: Magpie, label: string, run: MagpieRun) {
  note(`running ${label}: ${where.binary} ${run.args.join(' ')} <<< ${run.stdin.trim().split('\n').slice(0, 3).join('; ')}`)
  let result
  try {
    const ran = await $.process.run([where.binary, ...run.args], { cwd: where.cwd, stdin: unpackTiles(run.stdin), timeoutMs: RUN_TIMEOUT_MS })
    result = { ...ran, stdout: fromMagpie(ran.stdout), stderr: fromMagpie(ran.stderr) }
  } catch (error) {
    throw couldNotRun(where, error)
  }
  return { result, said: result.stdout + result.stderr }
}

/** A sim run as `execute` runs one, but streamed: each results table MAGPIE
 * prints as it goes is handed to `onTable` when it ends, so the pane fills
 * in while the sim runs. A run past RUN_TIMEOUT_MS is ended. */
async function executeStreaming(
  $: EngineInterface,
  where: Magpie,
  label: string,
  run: MagpieRun,
  onTable: (table: string) => Promise<void>,
) {
  note(`streaming ${label}: ${where.binary} ${run.args.join(' ')} <<< ${run.stdin.trim().split('\n').slice(0, 3).join('; ')}`)
  const started = Date.now()
  let stdout = ''
  let stderr = ''
  let handed = 0
  try {
    // Leaving the loop ends the child.
    for await (const { stream, text } of $.process.spawn({ argv: [where.binary, ...run.args], cwd: where.cwd, input: unpackTiles(run.stdin) })) {
      if (stream === 'stderr') {
        stderr = fromMagpie(stderr + text)
      } else {
        // Whole: a CRLF may come in two pieces.
        stdout = fromMagpie(stdout + text)
        const table = latestTable(stdout)
        if (table !== undefined && table.count > handed) {
          handed = table.count
          await onTable(table.text)
        }
      }
      if (Date.now() - started > RUN_TIMEOUT_MS) {
        stderr += `\nended after ${RUN_TIMEOUT_MS / 1000} s`
        break
      }
    }
  } catch (error) {
    throw couldNotRun(where, error)
  }
  return { result: { stdout, stderr }, said: stdout + stderr }
}

/** Works out what to sim, before anything runs: the position read or
 * fetched, and for a GCG which of its positions, or the ones that fit when
 * the person's turn, rack or word fits more than one. */
async function planSim($: EngineInterface, request: SimRequest): Promise<{ plan: Plan } | { candidates: GcgPosition[] }> {
  const already = await read($, running)
  if (already !== '') {
    throw new Error(`still running: ${already}`)
  }
  const { resolved, lexicon: knownLexicon } = await resolveRequest($, request)
  const where = await findMagpie($)
  let lexicon = knownLexicon
  let goto: string | undefined
  let label = request.label
  let turn: number | undefined
  let turns: number | undefined
  let mode: Mode = 'sim'
  if (resolved.kind === 'cgp') {
    // Unseen tiles counted from the lexicon's own set (102 tiles in French).
    const set = await tileSet($, where, runLexicon(resolved, lexicon))
    const setSize = set === undefined ? undefined : [...set.values()].reduce((total, count) => total + count, 0)
    mode = modeFor(cgpUnseen(resolved.cgp, setSize))
  }
  if (resolved.kind === 'gcg') {
    // Every position of the game, to find the one asked for. The scan also
    // learns whether the GCG names its lexicon (one MAGPIE fetched is
    // unread here).
    let scan = await execute($, where, label, scanRun(resolved.source, lexicon))
    if (lexicon === undefined && /without a specified lexicon/.test(scan.said)) {
      lexicon = preferredLexicon()
      scan = await execute($, where, label, scanRun(resolved.source, lexicon))
    }
    const positions = gcgPositions(scan.result.stdout)
    const choice = choosePosition(positions, request.at)
    if ('error' in choice) {
      throw new Error(
        positions.length === 0 ? magpieErrors(scan.result.stdout, scan.result.stderr, choice.error) : choice.error,
      )
    }
    if ('candidates' in choice) {
      return { candidates: choice.candidates }
    }
    turns = positions.length
    if ('goto' in choice) {
      goto = choice.goto
      label = `${label} event ${goto}`
    } else {
      goto = String(choice.position.events)
      turn = choice.position.turn
      mode = modeFor(choice.position.unseen)
      label = `${label} turn ${turn}`
    }
  }
  const plan: Plan = { request, resolved, goto, label, where, threadCount: await threads($), mode }
  if (lexicon !== undefined) {
    plan.lexicon = lexicon
  }
  if (turns !== undefined) {
    plan.turns = turns
  }
  if (turn !== undefined) {
    plan.turn = turn
  }
  return { plan }
}

/** What the person's turn, rack or word was, for the question. */
function selectorText(at: Selector | undefined): string {
  switch (at?.kind) {
    case 'rack':
      return `Rack ${at.rack}`
    case 'word':
      return `The word ${at.word}`
    case 'letters':
      return at.letters
    default:
      return 'That'
  }
}

function candidateLines(candidates: readonly GcgPosition[]): string[] {
  return candidates.map(candidate => `  ${describePosition(candidate)}`)
}

/** Runs a planned sim and makes it the one the pane shows. One at a time. */
async function runPlan($: EngineInterface, plan: Plan): Promise<Sim> {
  const already = await read($, running)
  if (already !== '') {
    throw new Error(`still running: ${already}`)
  }
  await update($, running, () => planStatus(plan))
  await update($, runError, () => '')
  try {
    const started = Date.now()
    const headerOf = (run: MagpieRun) =>
      [run.lexicon === '' ? '' : `# lexicon ${run.lexicon}`, `# label ${plan.label}`].filter(line => line !== '').join('\n')
    // A sim's tables as they come: the pane shows each, from the first on
    // with its own selection and scroll.
    let tables = 0
    const showTable = async (run: MagpieRun, table: string) => {
      await update($, simText, () => `${headerOf(run)}\n${table}`)
      if (++tables === 1) {
        await update($, selectedId, () => '')
        await update($, windowTop, () => 0)
      }
    }
    const magpie = async (accelerated: Accelerators) => {
      const run = magpieRun(plan.resolved, { lexicon: plan.lexicon, goto: plan.goto }, plan.threadCount, accelerated, plan.mode)
      const ran =
        plan.mode === 'sim'
          ? await executeStreaming($, plan.where, plan.label, run, table => showTable(run, table))
          : await execute($, plan.where, plan.label, run)
      return { run, result: ran.result, said: ran.said }
    }
    // The endgame solver has no use for them.
    const tried = plan.mode === 'endgame' ? { rit: false, wit: false } : await accelerators($, plan.where, plan.lexicon)
    let { run, result, said } = await magpie(tried)
    if ((tried.rit || tried.wit) && /not found for data type (rack|word) info table/.test(said)) {
      ;({ run, result } = await magpie({ rit: false, wit: false }))
    }
    // A streamed sim is kept as its last table, the one it finished on.
    const text = `${headerOf(run)}\n${latestTable(result.stdout)?.text ?? result.stdout}`
    let sim: Sim
    try {
      sim = parseSim(text)
    } catch {
      throw new Error(magpieErrors(result.stdout, result.stderr, 'MAGPIE printed no sim results'))
    }
    note(`${plan.label}: ${sim.plays.length} plays in ${((Date.now() - started) / 1000).toFixed(1)} s`)
    await update($, simText, () => text)
    // A game is kept at its turn, so moving from it and changing its
    // lexicon start from there.
    const shown: Current = {
      request: plan.turn === undefined ? plan.request : { ...plan.request, at: { kind: 'turn', turn: plan.turn } },
      label: plan.label,
      lexicon: run.lexicon !== '' ? run.lexicon : (plan.lexicon ?? ''),
    }
    if (plan.turn !== undefined && plan.turns !== undefined) {
      shown.turn = plan.turn
      shown.turns = plan.turns
    }
    await update($, current, () => JSON.stringify(shown))
    // A row picked while the sim streamed in stays picked.
    if (tables === 0) {
      await update($, selectedId, () => '')
      await update($, windowTop, () => 0)
    }
    return sim
  } catch (error) {
    const message = error instanceof Error ? error.message : String(error)
    note(`${plan.label} failed: ${message}`)
    await update($, runError, () => `${plan.label}: ${message}`)
    throw error
  } finally {
    await update($, running, () => '')
  }
}

type Column = {
  title: string
  sort?: SortKey
  isLeft?: true
  isCompact?: true
  cell: (play: Play) => string
}

const signed = (value: number) => (value > 0 ? '+' : '') + value.toFixed(2)

const COLUMNS: readonly Column[] = [
  // Cells as people read them: a Catalan tile in brackets (tiles.ts).
  { title: 'Play', sort: 'play', isLeft: true, isCompact: true, cell: play => unpackTiles(playName(play)) },
  { title: 'Leave', isLeft: true, cell: play => unpackTiles(play.leave) },
  { title: 'Sc', sort: 'score', isCompact: true, cell: play => String(play.score) },
  { title: 'Win%', sort: 'win', isCompact: true, cell: play => play.winPct.toFixed(2) },
  { title: '±', cell: play => play.winSe.toFixed(2) },
  { title: 'Eq', sort: 'equity', isCompact: true, cell: play => signed(play.equity) },
  { title: 'StEq', sort: 'static', cell: play => signed(play.staticEquity) },
  { title: 'Iters', sort: 'iterations', cell: play => String(play.iterations) },
  // The opponent's reply: its mean score and how often it bingoes.
  { title: 'OpSc', cell: play => play.plies[0]?.score.toFixed(1) ?? '' },
  { title: 'OpBn%', cell: play => play.plies[0]?.bingoPct.toFixed(1) ?? '' },
]

// An endgame's table: the final spread, what the line nets, and the rest of
// the line.
const ENDGAME_COLUMNS: readonly Column[] = [
  { title: 'Play', sort: 'play', isLeft: true, isCompact: true, cell: play => unpackTiles(playName(play)) },
  { title: 'Sc', sort: 'score', isCompact: true, cell: play => String(play.score) },
  { title: 'Result', sort: 'result', isCompact: true, cell: play => resultText(play.result) },
  { title: 'Net', sort: 'net', isCompact: true, cell: play => (play.net === undefined ? '' : `${play.net > 0 ? '+' : ''}${play.net}`) },
  { title: 'Then', isLeft: true, cell: play => unpackTiles(play.line ?? '') },
]
// The selection marker and the sim's rank, before the columns.
const RANK_WIDTH = 5

// A tile in a row of the table: two terminal columns, one row.
const TILE_COLUMNS = 2

/** The table's columns, each as wide as its widest cell, or its title with
 * room for a sort arrow, and the width of a whole row. With `tiles`, the
 * Play column (the first) spells each play as its square and a picture of
 * its tiles: the widest square label, and room for the most tiles. */
export type TableLayout = {
  columns: readonly { column: Column; width: number }[]
  width: number
  tiles?: { labelWidth: number; slots: number }
}

export function tableLayout(
  plays: readonly Play[],
  isCompact: boolean,
  isTiled = false,
  kind: Sim['kind'] = 'sim',
): TableLayout {
  const kindColumns = kind === 'endgame' ? ENDGAME_COLUMNS : COLUMNS
  const spelled = plays.map(playTiles)
  const tiles = isTiled
    ? {
        labelWidth: Math.max(0, ...spelled.map(play => play.label.length)),
        slots: Math.max(1, ...spelled.map(play => play.tiles.length)),
      }
    : undefined
  const columns = (isCompact ? kindColumns.filter(column => column.isCompact) : kindColumns).map(column => ({
    column,
    width: Math.max(
      column.title.length + (column.sort === undefined ? 0 : 1),
      ...(tiles !== undefined && column.sort === 'play'
        ? [tiles.labelWidth + 1 + TILE_COLUMNS * tiles.slots]
        : plays.map(play => column.cell(play).length)),
    ),
  }))
  const width = columns.reduce((total, { width: columnWidth }) => total + 1 + columnWidth, RANK_WIDTH)
  return tiles === undefined ? { columns, width } : { columns, width, tiles }
}

function sortValue(play: Play, key: SortKey): number {
  switch (key) {
    case 'win':
      return play.winPct
    case 'equity':
      return play.equity
    case 'score':
      return play.score
    case 'static':
      return play.staticEquity
    case 'iterations':
      return play.iterations
    case 'result':
      return play.result ?? 0
    case 'net':
      return play.net ?? 0
    case 'play':
      return 0
  }
}

export function sortPlays(plays: readonly Play[], key: SortKey, descending: boolean): Play[] {
  return [...plays].sort((a, b) => {
    const order = key === 'play' ? a.tiles.localeCompare(b.tiles) : sortValue(a, key) - sortValue(b, key)
    return (descending ? -order : order) || a.rank - b.rank
  })
}

// The first play the table shows: the stored one, moved just far enough to
// keep the selected play in view.
export function windowStart(top: number, index: number, room: number, count: number): number {
  const start = Math.min(Math.max(top, index - room + 1), index)
  return Math.min(Math.max(0, start), Math.max(0, count - room))
}

function pad(text: string, column: Column, width: number): string {
  return column.isLeft ? text.padEnd(width) : text.padStart(width)
}

export function headerLine(layout: TableLayout, key: SortKey, descending: boolean): string {
  const titles = layout.columns.map(({ column, width }) =>
    pad(column.title + (column.sort === key ? (descending ? '▼' : '▲') : ''), column, width),
  )
  return ['#'.padStart(RANK_WIDTH), ...titles].join(' ')
}

// The rank is the sim's own, by win%, whatever the table's order.
function rankCell(play: Play, isSelected: boolean): string {
  return (isSelected ? '▶' : ' ') + String(play.rank).padStart(RANK_WIDTH - 1)
}

export function rowLine(layout: TableLayout, play: Play, isSelected: boolean): string {
  const cells = layout.columns.map(({ column, width }) => pad(column.cell(play), column, width))
  return [rankCell(play, isSelected), ...cells].join(' ')
}

/** A tiled row's text either side of its tiles' picture: the rank and the
 * play's square, then the rest of the columns, so the row is as wide as
 * the header. */
export function rowParts(layout: TableLayout, play: Play, isSelected: boolean): { before: string; after: string } {
  const [playColumn, ...rest] = layout.columns
  if (layout.tiles === undefined || playColumn === undefined) {
    return { before: rowLine(layout, play, isSelected), after: '' }
  }
  const spelled = layout.tiles.labelWidth + 1 + TILE_COLUMNS * layout.tiles.slots
  return {
    before: `${rankCell(play, isSelected)} ${playTiles(play).label.padEnd(layout.tiles.labelWidth)} `,
    after:
      ' '.repeat(playColumn.width - spelled) +
      rest.map(({ column, width }) => ` ${pad(column.cell(play), column, width)}`).join(''),
  }
}

export function summaryLine(sim: Sim): string {
  const parts = [
    sim.label !== '' && sim.label !== sim.rack ? `${sim.label}, rack ${sim.rack}` : sim.rack,
    sim.lexicon,
    ...(sim.kind === 'endgame'
      ? [`endgame solved ${sim.plies} plies deep in ${sim.seconds.toFixed(1)} s`]
      : [
          `${sim.plies} ${sim.plies === 1 ? 'ply' : 'plies'}`,
          `${sim.iterations.toLocaleString('en-US')} iters in ${sim.seconds.toFixed(1)} s`,
        ]),
  ]
  return unpackTiles(parts.filter(part => part !== '').join(' · '))
}

/** The top plays as the simulate tool reports them to the model. */
export function reportLines(sim: Sim, count: number): string[] {
  return reportedLines(sim, count).map(unpackTiles)
}

function reportedLines(sim: Sim, count: number): string[] {
  if (sim.kind === 'endgame') {
    return sim.plays
      .slice(0, count)
      .map(
        play =>
          `${play.rank}. ${playName(play)}: ${play.score} pts, ${resultText(play.result)}, net ${play.net ?? 0}${play.line === '' || play.line === undefined ? '' : `; then ${play.line}`}`,
      )
  }
  return sim.plays
    .slice(0, count)
    .map(
      play =>
        `${play.rank}. ${playName(play)}${play.leave === '' ? '' : ` (keeps ${play.leave})`}: ${play.score} pts, win ${play.winPct.toFixed(2)}% ±${play.winSe.toFixed(2)}, equity ${signed(play.equity)}`,
    )
}

// A picture as a compressed PNG's base64, a small part of its pixels' size:
// what crosses to the terminal on each click, and what the tree's budget
// counts. Alpha where its clear pixels must stay clear.
function pngSource(picture: Picture, hasAlpha = false): string {
  return encodePng(picture.width, picture.height, picture.pixels, hasAlpha).toBase64()
}

// The bytes a picture's base64 decodes to, as the budget counts them.
const sourceBytes = (base64: string) => Math.floor((base64.length * 3) / 4)

// The selected play's picture as a PNG, the last few dozen kept: each is
// some 20 KB. The time a click waited on one is shown; one drawn ahead
// (`isAhead`) kept no one waiting.
function pictureSource(font: Font, sim: Sim, play: Play, isAhead = false) {
  let png = pictures.get(play.id)
  if (png === undefined) {
    const started = Date.now()
    png = pngSource(boardPicture(font, sim.board, sim.rack, play))
    if (!isAhead) {
      lastPictureMs = Date.now() - started
    }
    if (pictures.size >= PICTURES_KEPT) {
      const oldest = pictures.keys().next().value
      if (oldest !== undefined) {
        pictures.delete(oldest)
      }
    }
  } else {
    pictures.delete(play.id)
  }
  pictures.set(play.id, png)
  return { png }
}

// The sim whose listed plays' pictures are being drawn ahead.
let drawingAhead: Sim | null = null

/** Draws the listed plays' pictures ahead of any click, one each timer
 * tick so the pane's own events run between them: a click then finds its
 * picture made. Once a sim; a new one stops the last. */
function drawAhead($: EngineInterface, font: Font, sim: Sim) {
  if (drawingAhead === sim) {
    return
  }
  drawingAhead = sim
  const waiting = listedPlays(sim).filter(play => !pictures.has(play.id))
  const count = waiting.length
  const next = () => {
    const play = waiting.shift()
    if (drawingAhead !== sim) {
      return
    }
    if (play === undefined) {
      note(`drew ${count} pictures ahead`)
      return
    }
    if (!pictures.has(play.id)) {
      pictureSource(font, sim, play, true)
    }
    $.clock.after(DRAW_AHEAD_MS, next)
  }
  $.clock.after(DRAW_AHEAD_MS, next)
}

/** The plays the pane lists: the sim's top ones, as it ranks them. */
function listedPlays(sim: Sim): Play[] {
  return sim.plays.slice(0, PLAYS_LISTED)
}

async function sortedPlays($: EngineInterface, sim: Sim): Promise<Play[]> {
  return sortPlays(listedPlays(sim), await read($, sortKey), await read($, isDescending))
}

// Where the selected play stands in the table: the first play when nothing
// is selected yet, or the selection is not in this sim.
function selectedIndex(sorted: readonly Play[], id: string): number {
  return Math.max(0, sorted.findIndex(play => play.id === id))
}

/** A row's click: its play on the board. */
async function selectPlay($: EngineInterface, id: string) {
  if ((await read($, selectedId)) === id) {
    return
  }
  // Swap the picture at once; the redraw the write below causes draws the
  // same source, which sends nothing. Refused where no terminal picture is
  // mounted (the other surfaces draw an Svg), and a failed swap must not
  // stop the selection: that redraw draws the new picture anyway.
  const sim = await loadSim($)
  const play = sim.plays.find(candidate => candidate.id === id)
  if (play !== undefined && isTerminalDrawing) {
    try {
      await $.ui.blit({ requestId: PANE, key: 'board', source: pictureSource(await loadFont($), sim, play) })
    } catch {
      // The redraw below shows it.
    }
  }
  await update($, selectedId, () => id)
}

// The table's tile column as a PNG, for the sim loaded now, by the rows it
// shows and which is selected: clear around the tiles, so the pane shows
// through, the selected row on its colour, as its text is. The last few
// kept, so going back to a row draws nothing.
const columnPictures = new Map<string, string>()
const COLUMN_PICTURES_KEPT = 16

function tilesColumnSource(font: Font, plays: readonly Play[], selectedId: string, slots: number) {
  const key = `${slots}|${selectedId}|${plays.map(play => play.id).join('|')}`
  let png = columnPictures.get(key)
  if (png === undefined) {
    const rows = plays.map(play => ({
      tiles: playTiles(play).tiles,
      ...(play.id === selectedId && { background: SELECTED_ROW }),
    }))
    png = pngSource(tilesColumnPicture(font, rows, slots), true)
    if (columnPictures.size >= COLUMN_PICTURES_KEPT) {
      const oldest = columnPictures.keys().next().value
      if (oldest !== undefined) {
        columnPictures.delete(oldest)
      }
    }
    columnPictures.set(key, png)
  }
  return { png }
}

// The selected row's colour as text takes it, and the text on it.
const SELECTED_BACKGROUND = `#${SELECTED_ROW.map(channel => channel.toString(16).padStart(2, '0')).join('')}`
const SELECTED_TEXT = '#ffffff'


async function sortBy($: EngineInterface, key: SortKey) {
  if ((await read($, sortKey)) === key) {
    await update($, isDescending, descending => !descending)
  } else {
    await update($, sortKey, () => key)
    // Numbers sort high first, plays A to Z.
    await update($, isDescending, () => key !== 'play')
  }
  const sorted = await sortedPlays($, await loadSim($))
  const index = selectedIndex(sorted, await read($, selectedId))
  await update($, windowTop, top => windowStart(top, index, lastRoom, sorted.length))
}

async function openPane($: EngineInterface, title: string, focus: boolean): Promise<string> {
  const opened = await $.ui.open({
    id: PANE,
    title,
    focus: focus ? true : undefined,
    rows: PANE_ROWS,
    columns: PANE_COLUMNS,
  })
  return opened.isPlaced ? 'Opened the MAGPIE sim pane' : `The pane waits undrawn: ${opened.reason}`
}

async function currentTitle($: EngineInterface): Promise<string> {
  try {
    const sim = await loadSim($)
    return `MAGPIE · ${sim.label || sim.rack}`
  } catch {
    return 'MAGPIE'
  }
}

// The language the person plays in, the mod's option; their lexicon is
// magpie.ts's preferredLexicon.
let language = 'English'

const NOT_INSTALLED = 'MAGPIE, which runs the sims, is not installed yet'
// A reply put in the person's language: long enough for any the mod writes.
const TRANSLATION_MAX_TOKENS = 1000

/** A reply of the mod's in the person's language: its messages are English,
 * so the quick model writes them again in theirs, the plays, racks and
 * squares as they are. As it is in English, or when the model does not
 * answer. */
async function inLanguage($: EngineInterface, text: string): Promise<string> {
  const target = englishNameOf(language)
  if (target === 'English' || text.trim() === '') {
    return text
  }
  const reply = await $.model.complete({
    model: INTERPRETER_MODEL,
    system: `You translate the replies of /magpie, a command that analyzes crossword (Scrabble) positions, into ${target}. Keep exactly as written: plays and coordinates (8G VAV, H8 (I)NERTIAS, -EO), racks and words in capitals, tiles in brackets ([NY]), lexicon names, numbers, file paths, URLs, and commands (/magpie ...). Keep the line breaks. Reply with the translation and nothing else.`,
    prompt: text,
    maxTokens: TRANSLATION_MAX_TOKENS,
    timeoutMs: INTERPRETER_TIMEOUT_MS,
  })
  if (!reply.isAnswered || reply.text.trim() === '') {
    note(`could not translate into ${target}: ${reply.isAnswered ? 'empty' : reply.reason}`)
    return text
  }
  return reply.text.trim()
}

// Whether MAGPIE and its data are where the mod runs them.
async function isInstalled($: EngineInterface): Promise<boolean> {
  const where = await findMagpie($)
  return (await $.fs.exists(where.binary)) && (where.cwd === undefined || (await $.fs.exists(`${where.cwd}/data/lexica`)))
}

async function openSetup($: EngineInterface, focus: boolean): Promise<string> {
  const opened = await $.ui.open({
    id: SETUP_PANE,
    title: 'MAGPIE setup',
    focus: focus ? true : undefined,
    rows: SETUP_ROWS,
    columns: SETUP_COLUMNS,
  })
  return opened.isPlaced ? 'Opened the MAGPIE setup pane' : `The setup pane waits undrawn: ${opened.reason}`
}

// Opens the setup pane by itself at the session's start while MAGPIE is
// missing, unless the person said not now.
async function offerSetup($: EngineInterface) {
  if ((await isInstalled($)) || (await $.store.get(SETUP_DECLINED)) === true) {
    return
  }
  note(`MAGPIE is missing: ${await openSetup($, false)}`)
}

// The language and lexicon the setup pane shows: its picks, else the options.
async function setupChoices($: EngineInterface): Promise<{ language: string; lexicon: string }> {
  return {
    language: (await read($, setupLanguage)) || language,
    lexicon: (await read($, setupLexicon)) || preferredLexicon(),
  }
}

let setupRun: Promise<boolean> | null = null

async function pickLanguage($: EngineInterface, name: string) {
  if (setupRun !== null) {
    return
  }
  const { lexicon } = await setupChoices($)
  await update($, setupLanguage, () => name)
  if (languageOf(lexicon) !== name) {
    await update($, setupLexicon, () => firstLexicon(name))
  }
}

async function pickLexicon($: EngineInterface, name: string) {
  if (setupRun === null) {
    await update($, setupLexicon, () => name)
  }
}

// Installs what is missing for the choices, then keeps them as the mod's
// options, as /config shows them.
async function startSetup($: EngineInterface) {
  if (setupRun !== null) {
    return
  }
  const choices = await setupChoices($)
  const where = await findMagpie($)
  const plan = { host: await hostNow($), dir: where.cwd ?? '', lexicon: choices.lexicon, threads: await threads($) }
  let progress: SetupProgress | undefined
  setupRun = installMagpie($, plan, async shown => {
    progress = shown
    await update($, setup, () => JSON.stringify(shown))
  })
  const isDone = await setupRun.finally(() => {
    setupRun = null
  })
  note(`setup ${isDone ? 'done' : `stopped: ${progress?.problem ?? ''}`}`)
  if (!isDone || progress === undefined) {
    return
  }
  lexicaList = null
  await $.store.delete(SETUP_DECLINED)
  const saved = await saveChoices($, choices)
  await update($, setup, () => JSON.stringify({ ...progress, saved }))
}

// The choices as the mod's options, which a change reloads it with; meanwhile
// this session uses them. Says what could not be saved.
async function saveChoices($: EngineInterface, choices: { language: string; lexicon: string }): Promise<string> {
  const unsaved: string[] = []
  for (const [field, value, was] of [
    ['language', choices.language, language],
    ['lexicon', choices.lexicon, preferredLexicon()],
  ] as const) {
    if (value === was) {
      continue
    }
    const result = await $.config.set({ key: `${PLUGIN}.${field}`, value }).catch((error: unknown) => ({ deny: String(error) }))
    if ('deny' in result && result.deny !== undefined) {
      note(`could not save the ${field}: ${result.deny}`)
      unsaved.push(field)
    }
  }
  language = choices.language
  setPreferredLexicon(choices.lexicon)
  return unsaved.length === 0
    ? ''
    : `The ${unsaved.join(' and ')} hold for this session; to keep them, set them in /config (${PLUGIN}).`
}

async function declineSetup($: EngineInterface) {
  await $.store.set(SETUP_DECLINED, true)
  await $.ui.close({ id: SETUP_PANE })
}

// Apple's installer of its command-line tools, which building on a Mac needs.
async function getAppleTools($: EngineInterface) {
  const started = await $.process.run(['xcode-select', '--install']).catch(() => undefined)
  note(`xcode-select --install: ${started === undefined ? 'did not start' : `exit ${started.exitCode}`}`)
}

const SIM_SHAPE = `${SIM_PLAYS} plays ×${ITERATIONS_PER_PLAY.toLocaleString('en-US')} iterations, ${SIM_PLIES} plies`

// Where the latest prompt came from: `bridge` for the phone (or the web) over
// Remote Control, where no pane draws, so a sim answers with a picture.
let lastPromptOrigin = ''

let pictureDirectory: Promise<string> | null = null

// Pictures go in the temporary directory, `magpie-sim` in it.
function pictureFolder($: EngineInterface): Promise<string> {
  pictureDirectory ??= (async () => {
    const temporary = (await $.env.get('TMPDIR')) ?? (await $.env.get('TEMP')) ?? '/tmp'
    return `${temporary.replace(/[\\/]$/, '')}/magpie-sim`
  })()
  return pictureDirectory
}

function cardSubtitle(sim: Sim): string {
  return summaryLine({ ...sim, label: '' })
}

/** The picture of what the pane shows (or of `sim`) as a PNG file, for a
 * phone, which shows a file and no pane: its path and a caption. */
async function makePicture($: EngineInterface, given?: Sim): Promise<{ file: string; caption: string }> {
  const sim = given ?? (await loadSim($))
  const id = await read($, selectedId)
  const shown = sim.plays.find(play => play.id === id) ?? sim.plays[0]
  if (shown === undefined) {
    throw new Error('there are no plays to show')
  }
  const picture = cardPicture(await loadFont($), sim, shown, sim.label || sim.rack, cardSubtitle(sim))
  const directory = await pictureFolder($)
  const name = `${(sim.label || sim.rack).replace(/[^\p{L}\p{N}]+/gu, '-').slice(0, 60)}-${Date.now()}`
  const raw = `${directory}/${name}.raw.png`
  const path = `${directory}/${name}.png`
  // The file is binary and $.fs writes text: its base64 decoded on the way,
  // on Windows by certutil from a file $.fs writes (folders and all).
  const base64 = encodePng(picture.width, picture.height, picture.pixels).toBase64()
  const machine = await hostNow($)
  let wrote
  if (machine.os === 'windows') {
    await $.fs.write(`${raw}.b64`, base64)
    wrote = await $.process.run(['certutil', '-f', '-decode', windowsPath(`${raw}.b64`), windowsPath(raw)])
  } else {
    wrote = await $.process.run(['sh', '-c', 'mkdir -p "$1" && base64 --decode > "$2"', 'magpie-sim', directory, raw], {
      stdin: base64,
    })
  }
  if (wrote.exitCode !== 0) {
    throw new Error(`could not write the picture: ${(wrote.stderr || wrote.stdout).trim()}`)
  }
  // On a Mac, sips writes it smaller still.
  const squeezed =
    machine.os === 'macos' ? await $.process.run(['sips', '-s', 'format', 'png', raw, '--out', path]).catch(() => undefined) : undefined
  const file = squeezed?.exitCode === 0 ? path : raw
  note(`drew ${file}`)
  return { file, caption: `${sim.label || sim.rack}: ${sim.kind === 'endgame' ? 'the endgame solved' : 'the top plays'}` }
}

/** What has Claude send a picture: a file card reaches the phone only as a
 * SendUserFile call of the conversation's own, which a plugin's
 * $.tool.call is not. */
function sendInstruction({ file, caption }: { file: string; caption: string }): string {
  return `Send the person this picture with SendUserFile (display "render", caption "${caption}"), as their phone shows no pane: ${file}`
}

/** The picture sent from outside a turn (a /magpie from the phone): a prompt
 * for Claude to send it, its own short turn once the session is idle. The
 * engine refuses a prompt from inside a command's hook, which holds the turn
 * it would wait on, so it goes from a timer of its own. */
async function sendPicture($: EngineInterface, given?: Sim): Promise<void> {
  const text = sendInstruction(await makePicture($, given))
  $.clock.after(PROMPT_DELAY_MS, () => {
    $.prompt.submit({ text }).catch((error: unknown) => note(`could not ask for the picture: ${String(error)}`))
  })
}

let lexicaList: Promise<string[]> | null = null

// The question the last /magpie asked, kept for the next one to answer
// briefly: "the second z", "14G". A question whose answer the pane already
// stands on (the rack still to come) is not kept.
let asked: { typed: string[]; question: string } | undefined

// The lexicons the MAGPIE directory has (its .kwg files); none known for the
// magpie on PATH.
async function lexica($: EngineInterface): Promise<string[]> {
  lexicaList ??= findMagpie($).then(async where =>
    where.cwd === undefined
      ? []
      : (await $.fs.list(`${where.cwd}/data/lexica`).catch(() => []))
          .map(entry => /^(.+)\.kwg$/.exec(entry.name)?.[1])
          .filter((name): name is string => name !== undefined)
          .sort(),
  )
  return lexicaList
}

/** What the person typed after /magpie, read by a model into an Intent with
 * what the pane shows and the lexicons at hand. */
async function interpret($: EngineInterface, text: string): Promise<Intent> {
  const shown = await readCurrent($)
  const context: InterpreterContext = { lexica: await lexica($) }
  if (asked !== undefined) {
    context.asked = asked
  }
  if (shown !== undefined) {
    // The moves played on from the position's start, and, unless its rack is
    // still to come, the rack and the plays the pane ranks.
    const after = shown.request.position.after ?? []
    const isAwaitingRack = shown.request.position.rack === ''
    const sim = isAwaitingRack ? undefined : await loadSim($).catch(() => undefined)
    context.current = {
      label: shown.label,
      source: shown.request.source,
      lexicon: shown.lexicon,
      ...(shown.turn === undefined ? {} : { turn: shown.turn, turns: shown.turns }),
      moves: after.map(move => (move.coordinate === 'pass' ? 'pass' : `${move.coordinate} ${move.word}`)),
      rack: sim?.rack ?? '',
      topPlays: (sim?.plays ?? []).slice(0, TOP_PLAYS_TOLD).map(play => `${playName(play)} ${play.score}`),
    }
  }
  const { system, prompt } = interpreterPrompt(text, context)
  const reply = await $.model.complete({
    model: INTERPRETER_MODEL,
    system,
    prompt,
    maxTokens: INTERPRETER_MAX_TOKENS,
    timeoutMs: INTERPRETER_TIMEOUT_MS,
  })
  if (!reply.isAnswered) {
    throw new Error(`the model reading it did not answer (${reply.reason})`)
  }
  note(`read "${text}" as ${reply.text.trim()}`)
  return parseIntent(reply.text)
}

// A position nobody has shown yet: the empty board, its rack to come.
const EMPTY_BOARD: SimRequest = { position: { kind: 'rack', rack: '', after: [] }, label: 'the opening', source: '' }
// The placements a question lists when a move fits several.
const PLACEMENTS_LISTED = 6

const placed = (move: PlacedMove) => (move.coordinate === 'pass' ? 'pass' : `${move.coordinate} ${move.word}`)

function describeMove(move: MoveDescription): string {
  const parts = [
    move.square === undefined ? '' : `at ${move.square}`,
    move.direction ?? '',
    move.score === undefined ? '' : `for ${move.score}`,
    ...(move.through ?? []).map(({ letter, word }) => `through the ${letter}${word === undefined ? '' : ` of ${word}`}`),
    move.premium === undefined ? '' : `to a ${move.premium}`,
  ]
  return [move.word, ...parts].filter(part => part !== '').join(' ')
}

// The set of tiles the lexicon's games use, from MAGPIE's own data; none
// known for the magpie on PATH, or a set of many-letter tiles.
async function tileSet($: EngineInterface, where: Magpie, lexicon: string | undefined): Promise<Tiles | undefined> {
  const name = distributionName(lexicon ?? preferredLexicon())
  if (name === undefined || where.cwd === undefined) {
    return undefined
  }
  return $.fs
    .read(`${where.cwd}/data/letterdistributions/${name}.csv`)
    .then(parseDistribution)
    .catch(() => undefined)
}

const scoresOfSets = new Map<string, Readonly<Record<string, number>>>()

// What each tile of the lexicon's set scores, from MAGPIE's own data;
// English's while that cannot be read.
async function scoresFor($: EngineInterface, lexicon: string): Promise<Readonly<Record<string, number>>> {
  const name = distributionName(lexicon || preferredLexicon()) ?? 'english'
  const known = scoresOfSets.get(name)
  if (known !== undefined) {
    return known
  }
  const where = await findMagpie($)
  const csv = await $.fs.read(`${where.cwd}/data/letterdistributions/${name}.csv`).catch(() => '')
  const scores = parseScores(csv)
  if (Object.keys(scores).length === 0) {
    return TILE_SCORES
  }
  scoresOfSets.set(name, scores)
  return scores
}

/** Why the rack a plan moves with cannot be, before a sim waits on it:
 * MAGPIE's own check (`rack` on the position reached, a quick run), said
 * with the tiles short where the set's counts tell. */
async function rackProblem($: EngineInterface, plan: Plan): Promise<string | undefined> {
  const rack = plan.resolved.rack
  if (rack === undefined || rack === '') {
    return undefined
  }
  const run = generateRun(plan.resolved, { lexicon: plan.lexicon, goto: plan.goto }, [])
  const { result, said } = await execute($, plan.where, `checking ${rack}`, { ...run, stdin: `${run.stdin}rack ${rack}\n` })
  if (!/is not available in the bag/.test(said)) {
    return undefined
  }
  const set = await tileSet($, plan.where, plan.lexicon)
  const missing = set === undefined ? [] : missingTiles(rack, tilesLeft(set, parseBoard(result.stdout.split('\n')) ?? []))
  return `${rack} cannot be the correct rack: ${missing.length > 0 ? missingText(missing) : 'the bag does not hold its tiles'}.`
}

/** A play intent's moves found on the board in order, each a legal play of
 * the word as described, and the position they reach: the request to sim,
 * or what to ask instead: a move that fits nowhere or cannot be had from
 * the tiles left, several places the opponent's fits, which tile was a
 * blank, a leave or rack the tiles do not allow, or the rack itself. */
async function resolvePlay(
  $: EngineInterface,
  intent: Extract<Intent, { action: 'play' }>,
  shown: Current | undefined,
): Promise<{ request: SimRequest; message?: string } | { answer: string; reopen?: true; followUp?: true }> {
  const base = shown?.request ?? EMPTY_BOARD
  const isShownSim = shown !== undefined && (shown.request.position.rack ?? 'known') !== ''
  const sim = isShownSim ? await loadSim($).catch(() => undefined) : undefined
  if (intent.moves[0]?.by === 'opponent' && sim !== undefined) {
    return {
      followUp: true,
      answer: `In ${shown?.label ?? 'the pane'} it is your move, with ${sim.rack}: what did you play before ${intent.moves[0].word || 'that'}?`,
    }
  }
  // What reaches the base position: the scan of a game, a CGP's lexicon.
  const planned = await planSim($, { ...base, position: { ...base.position, rack: '' } })
  if ('candidates' in planned) {
    throw new Error(`which position of ${base.label} is not clear`)
  }
  const plan = planned.plan
  const reach = { lexicon: plan.lexicon, goto: plan.goto }
  const set = await tileSet($, plan.where, plan.lexicon ?? shown?.lexicon)
  const baseAfter = base.position.after ?? []
  const played: PlacedMove[] = []
  const notes: string[] = []
  const at = (moves: readonly PlacedMove[]): Resolved => {
    const position: Resolved = { ...plan.resolved, after: [...baseAfter, ...moves] }
    delete position.rack
    return position
  }
  // The board as the moves leave it, from MAGPIE's own print of the base.
  const first = await execute($, plan.where, 'reading the board', generateRun(at([]), reach, []))
  let board = parseBoard(first.result.stdout.split('\n')) ?? []
  // The person's tiles kept on their latest move, which their next rack
  // holds: before these moves, the one before the opponent's last.
  const ownLast = baseAfter[baseAfter.length - 2]
  let personLeave = ownLast?.leave === undefined ? undefined : { leave: ownLast.leave, word: ownLast.word }
  // Whose the last move was: the person's leaves the opponent to move.
  let isLastPerson = false
  for (const [index, move] of intent.moves.entries()) {
    const isPerson = move.by === 'me' || (move.by === undefined && index % 2 === 0)
    isLastPerson = isPerson
    if (move.pass === true) {
      played.push({ coordinate: 'pass', word: '' })
      notes.push('a pass')
      continue
    }
    // The person's own first move is from the rack the pane shows. Another's
    // tiles are unknown: the word's own letters stand in, a blank for each
    // letter the tiles left cannot supply.
    const isMine = index === 0 && sim !== undefined && move.by !== 'opponent'
    let racks = isMine ? [sim.rack] : racksFor(move)
    if (racks.length === 0) {
      return { followUp: true, answer: `${move.word} is too long to find without its square: say where it went (H8, 8H).` }
    }
    if (!isMine && set !== undefined) {
      const left = tilesLeft(set, board, isPerson ? '' : (personLeave?.leave ?? ''))
      const tried = racks.map(rack => withBlanks(rack, left))
      const possible = tried.flatMap(attempt => ('rack' in attempt ? [attempt.rack] : []))
      const short = tried.find(attempt => 'short' in attempt)
      if (possible.length === 0 && short !== undefined && 'short' in short) {
        return { followUp: true, answer: `${shortText(move.word, short.short)}: that cannot have been played.` }
      }
      racks = possible
    } else if (!isMine) {
      racks = racks.map(rack => rack.replace(/\p{Ll}/gu, '?'))
    }
    const { result } = await execute($, plan.where, `finding ${move.word}`, generateRun(at(played), reach, racks))
    // MAGPIE's own print of the board this move went on.
    board = parseBoard(result.stdout.split('\n')) ?? board
    const legal = new Map(parseGenerated(result.stdout).flat().map(play => [`${play.coordinate} ${play.word}`, play]))
    const fits = [...legal.values()].filter(play => fitsDescription(play, move, board))
    if (fits.length === 0) {
      const anywhere = [...legal.values()].filter(play => fitsDescription(play, { word: letters(move.word) }, board))
      const why = magpieErrors(result.stdout, result.stderr, '')
      return {
        followUp: true,
        answer: [
          `${describeMove(move)} is not a legal play here${why === '' ? '' : ` (${why})`}.`,
          anywhere.length === 0
            ? isMine
              ? `${move.word} cannot be played from ${sim.rack} on this board: is the word right, or was the rack another?`
              : `${move.word} fits nowhere on this board: is the word right?`
            : `${move.word} fits at ${anywhere
                .slice(0, PLACEMENTS_LISTED)
                .map(play => `${play.coordinate} ${play.word} ${play.score}`)
                .join(', ')}: which?`,
        ].join(' '),
      }
    }
    // A placement is its square and its letters; which tile a blank was is
    // asked apart. The person's own: the best the sim ranked (the play it
    // showed), else the best by equity. Another's in more than one place: ask.
    const where = (play: GeneratedPlay) => `${play.coordinate} ${letters(play.word)}`
    const rank = (play: GeneratedPlay) => {
      const found = sim?.plays.findIndex(simmed => simmed.id === `${play.coordinate} ${play.word}`) ?? -1
      return found < 0 ? Number.MAX_SAFE_INTEGER : found
    }
    const ranked = [...fits].sort((a, b) => rank(a) - rank(b) || b.equity - a.equity || b.score - a.score)
    const placements = [...new Set(ranked.map(where))]
    if (placements.length > 1 && !isMine) {
      return {
        followUp: true,
        answer: [
          `${describeMove(move)} fits ${placements.length} places:`,
          ...placements.slice(0, PLACEMENTS_LISTED).map(placement => {
            const play = ranked.find(candidate => where(candidate) === placement) as GeneratedPlay
            return `  ${play.coordinate} ${play.word} for ${play.score}`
          }),
          'Which? Say its square or score.',
        ].join('\n'),
      }
    }
    const best = ranked[0] as GeneratedPlay
    const blanks = ranked.filter(play => where(play) === where(best))
    if (blanks.length > 1) {
      // In the order the blank comes in the word, each named by its place.
      const firstBlank = (word: string) => word.replace(/\([^)]*\)/g, through => through.toUpperCase()).search(/\p{Ll}/u)
      return {
        followUp: true,
        answer: `Which tile of ${letters(move.word)} at ${best.coordinate} was the blank: ${[...blanks]
          .sort((a, b) => firstBlank(a.word) - firstBlank(b.word))
          .map(play => `${blankText(play.word)} (${play.word}, ${play.score})`)
          .join(' or ')}?`,
      }
    }
    // The leave: the person's own from the rack the pane shows, checked
    // against what they said; another's as said, if the tiles left allow it.
    const tiles = tilesFromRack(best.word)
    let leave = move.leave
    if (isMine) {
      const kept = rackLess(sim.rack, tiles) ?? ''
      if (leave !== undefined && !sameTiles(leave, kept)) {
        return { followUp: true, answer: `From ${sim.rack}, ${best.word} keeps ${kept || 'nothing'}, not ${leave}: which is right?` }
      }
      leave = kept
    } else if (leave !== undefined && set !== undefined) {
      const missing = missingTiles(tiles + leave, tilesLeft(set, board, isPerson ? '' : (personLeave?.leave ?? '')))
      if (missing.length > 0) {
        return { followUp: true, answer: `${best.word} keeping ${leave} cannot be: ${missingText(missing)}.` }
      }
    }
    played.push(leave === undefined || leave === '' ? { coordinate: best.coordinate, word: best.word } : { coordinate: best.coordinate, word: best.word, leave })
    board = applyMove(board, best.coordinate, best.word)
    if (isPerson) {
      personLeave = leave === undefined || leave === '' ? undefined : { leave, word: best.word }
    }
    notes.push(
      `${best.coordinate} ${best.word} for ${best.score}${isMine && placements.length > 1 ? ' (the top of its placements)' : ''}`,
    )
  }
  const after = [...baseAfter, ...played]
  const rack = intent.rack ?? ''
  const playedText = notes.length === 0 ? '' : `Played ${notes.join(', then ')}. `
  const recent = after.slice(-2).map(placed).join(', ')
  const withRack = (held: string): SimRequest => ({
    ...base,
    position: { ...base.position, after, rack: held } as SimRequest['position'],
    label: `${held === '' ? 'next' : held} after ${after.length > 2 ? '…, ' : ''}${recent}`,
  })
  // After the person's own move it is the opponent's turn: what they did
  // is asked, and the answer read with all of this.
  if (isLastPerson) {
    const last = played[played.length - 1]
    return {
      followUp: true,
      answer: `${playedText}It is your opponent's turn after ${last === undefined ? 'that' : placed(last)}: what did they play, or did they pass?`,
    }
  }
  // A rack the tiles left cannot make, or one without the tiles kept.
  let problem: string | undefined
  if (rack !== '' && set !== undefined) {
    const missing = missingTiles(rack, tilesLeft(set, board))
    if (missing.length > 0) {
      problem = `${rack} cannot be the correct rack: ${missingText(missing)}. What is your rack?`
    }
  }
  if (rack !== '' && problem === undefined && personLeave !== undefined && rackLess(rack, personLeave.leave) === null) {
    problem = `You kept ${personLeave.leave} after ${personLeave.word}, but ${rack} does not hold it. What is your rack?`
  }
  if (rack === '' || problem !== undefined) {
    // The moves kept as what the pane stands on, so the rack alone can follow.
    const pending = withRack('')
    await update($, current, () =>
      JSON.stringify({ request: pending, label: pending.label, lexicon: shown?.lexicon ?? plan.lexicon ?? '' } satisfies Current),
    )
    return { answer: `${playedText}${problem ?? 'What rack do you have now?'}` }
  }
  return { request: withRack(rack), message: `${playedText}Simulating ${rack}` }
}

/** The request an intent makes, against what the pane shows; or the answer
 * itself, when there is nothing to run (a question, the pane reopened, a
 * lexicon already in use, the end of the game reached). */
async function requestFor(
  $: EngineInterface,
  intent: Intent,
): Promise<
  { request: SimRequest; message?: string } | { answer: string; reopen?: true; picture?: true; followUp?: true; setup?: true }
> {
  const shown = await readCurrent($)
  switch (intent.action) {
    case 'unclear':
      return { answer: intent.question, followUp: true }
    case 'setup':
      return { answer: 'Pick the language and lexicon you play in there.', setup: true }
    case 'reopen':
      return { answer: 'Opened the MAGPIE sim pane.', reopen: true }
    case 'play':
      return resolvePlay($, intent, shown)
    case 'picture':
      return shown === undefined
        ? { answer: 'There is nothing to show yet: sim a position first.' }
        : { answer: `Sent a picture of ${shown.label}.`, picture: true }
    case 'navigate': {
      if (shown?.turn === undefined || shown.turns === undefined) {
        return { answer: 'The pane shows no game to move through: sim a GCG first (/magpie <path or URL of a .gcg>).' }
      }
      const turn =
        intent.to === 'next'
          ? shown.turn + 1
          : intent.to === 'previous'
            ? shown.turn - 1
            : intent.to === 'first'
              ? 1
              : shown.turns
      if (turn < 1 || turn > shown.turns) {
        return { answer: `Turn ${shown.turn} is the game's ${turn < 1 ? 'first' : 'last'}.` }
      }
      if (turn === shown.turn) {
        return { answer: `The pane already shows turn ${turn}.`, reopen: true }
      }
      return { request: { ...shown.request, at: { kind: 'turn', turn } } }
    }
    case 'lexicon': {
      if (shown === undefined) {
        return { answer: 'There is nothing to analyze again yet: sim a position first.' }
      }
      const lexicon = checkLexicon(intent.lexicon, await lexica($))
      if (lexicon === shown.lexicon) {
        return { answer: `Already using ${lexicon} for ${shown.label}.`, reopen: true }
      }
      return {
        request: { ...shown.request, lexicon },
        message: `Analyzing ${shown.label} again in ${lexicon}${shown.lexicon === '' ? '' : ` (was ${shown.lexicon})`}`,
      }
    }
    case 'sim': {
      const request = requestFromIntent(intent, shown?.request)
      if (request.lexicon !== undefined) {
        request.lexicon = checkLexicon(request.lexicon, await lexica($))
      }
      return { request }
    }
  }
}

/** What the person's turn, rack or word was, for the question. */
function askWhich(request: SimRequest, candidates: readonly GcgPosition[]): string[] {
  return [
    `${selectorText(request.at)} fits ${candidates.length} positions in ${request.label}:`,
    ...candidateLines(candidates),
  ]
}

/** What /magpie answers, in English: a question, what it opened, or that a
 * sim runs. A command from the phone (`fromPhone`) gets a picture.
 */
async function magpieCommand($: EngineInterface, args: string, fromPhone: boolean): Promise<{ text: string }> {
  if (args === 'why') {
    const panes = (await $.ui.panes()).map(
      pane => `${pane.id} placed=${pane.isPlaced} shown=${pane.isShown} focused=${pane.isFocused}`,
    )
    return {
      text: [
        `Surfaces attached: ${(await $.session.surfaces()).join(', ') || 'none'}.`,
        `Open panes: ${panes.join('; ') || 'none'}.`,
        `What the mod did:${log.length === 0 ? ' nothing yet' : ''}`,
        ...log,
      ].join('\n'),
    }
  }
  if (args === 'setup') {
    return { text: `${await openSetup($, true)}.` }
  }
  if (!(await isInstalled($))) {
    return { text: `${NOT_INSTALLED}. ${await openSetup($, true)}: press Install there.` }
  }
  let found: Awaited<ReturnType<typeof requestFor>>
  let planned: Awaited<ReturnType<typeof planSim>>
  // A question this one does not answer is dropped: what was typed up to
  // it is kept while the questions go on, the last few of it.
  const previous = asked
  const ask = (question: string) => {
    asked = { typed: [...(previous?.typed ?? []), args].slice(-ASKED_KEPT), question }
    return question
  }
  try {
    found =
      args === ''
        ? { answer: 'Opened the MAGPIE sim pane.', reopen: true }
        : await requestFor($, await interpret($, args))
    asked = undefined
    if ('answer' in found) {
      if (found.followUp === true) {
        ask(found.answer)
      }
      if (found.reopen === true) {
        await openPane($, await currentTitle($), true)
      }
      if (found.setup === true) {
        return { text: `${await openSetup($, true)}. ${found.answer}` }
      }
      if (found.picture === true || (fromPhone && found.reopen === true)) {
        await sendPicture($)
      }
      return { text: found.answer }
    }
    planned = await planSim($, found.request)
  } catch (error) {
    return { text: error instanceof Error ? error.message : String(error) }
  }
  if ('candidates' in planned) {
    const first = planned.candidates[0]
    return {
      text: ask(
        [
          ...askWhich(found.request, planned.candidates),
          `Say which, e.g. /magpie ${found.request.source} turn ${first?.turn ?? 1}`,
        ].join('\n'),
      ),
    }
  }
  const plan = planned.plan
  try {
    const problem = await rackProblem($, plan)
    if (problem !== undefined) {
      const text = `${found.message?.replace(/Simulating .*$/, '') ?? ''}${problem} What is the rack?`
      // Moves typed out are kept, the pane standing on them, for the rack
      // alone to follow; anything else is asked again.
      if ((found.request.position.after ?? []).length === 0) {
        return { text: ask(text) }
      }
      const pending: SimRequest = {
        ...found.request,
        position: { ...found.request.position, rack: '' },
        label: found.request.label.replace(/^\S+ after /, 'next after '),
      }
      await update($, current, () =>
        JSON.stringify({ request: pending, label: pending.label, lexicon: plan.lexicon ?? '' } satisfies Current),
      )
      return { text }
    }
  } catch (error) {
    return { text: error instanceof Error ? error.message : String(error) }
  }
  const opened = await openPane($, `MAGPIE · ${plan.label}`, true)
  // The sim outlives the command: the pane shows it running, then its
  // results, or what went wrong.
  void runPlan($, plan)
    .then(sim => (fromPhone ? sendPicture($, sim) : undefined))
    .catch((error: unknown) => note(`${plan.label}: ${String(error)}`))
  return {
    text: `${opened}. ${found.message === undefined ? planStatus(plan) : `${found.message} in ${lexiconText(plan)}`}. ${fromPhone ? 'A picture follows' : 'The pane fills in'} when it finishes.`,
  }
}

/** What the simulate tool answers Claude: the top plays, or why not. */
async function simulateTool($: EngineInterface, input: Record<string, unknown>): Promise<{ result: string } | { deny: string }> {
  let request: SimRequest
  let planned: Awaited<ReturnType<typeof planSim>>
  if (!(await isInstalled($))) {
    return {
      result: `Not run: ${NOT_INSTALLED}. ${await openSetup($, false)}; ask the person to press Install there (it gets MAGPIE ${MAGPIE_VERSION} and about 195 MB of word lists), then call again.`,
    }
  }
  try {
    // The caller is a model already: its fields are the intent.
    const found = await requestFor($, parseIntent(JSON.stringify({ ...input, action: 'sim' })))
    if ('answer' in found) {
      return { result: found.answer }
    }
    request = found.request
    planned = await planSim($, request)
  } catch (error) {
    return { deny: `${PLUGIN}: ${error instanceof Error ? error.message : String(error)}` }
  }
  if ('candidates' in planned) {
    return {
      result: [
        'Not run.',
        ...askWhich(request, planned.candidates),
        'Ask the person which they mean, then call again with `turn` set to it.',
      ].join('\n'),
    }
  }
  const plan = planned.plan
  let sim: Sim
  try {
    const problem = await rackProblem($, plan)
    if (problem !== undefined) {
      return { result: `Not run. ${problem} Ask the person for their rack.` }
    }
  } catch (error) {
    return { deny: `${PLUGIN}: ${error instanceof Error ? error.message : String(error)}` }
  }
  const opened = await openPane($, `MAGPIE · ${plan.label}`, false)
  try {
    sim = await runPlan($, plan)
  } catch (error) {
    return { deny: `${PLUGIN}: the sim of ${plan.label} failed: ${error instanceof Error ? error.message : String(error)}` }
  }
  let pictureLine = 'If the pane waits undrawn, the person can type /magpie to open it.'
  // The caller is in a turn: it sends the picture itself.
  if (input.picture === true || lastPromptOrigin === 'bridge') {
    try {
      pictureLine = sendInstruction(await makePicture($, sim))
    } catch (error) {
      pictureLine = `The picture could not be drawn: ${error instanceof Error ? error.message : String(error)}`
    }
  }
  return {
    result: [
      `${opened}. ${summaryLine(sim)}, ${sim.plays.length} plays. Top ${sim.kind === 'endgame' ? 'by the solver' : 'by win%'}:`,
      ...reportLines(sim, PLAYS_REPORTED),
      pictureLine,
    ].join('\n'),
  }
}

export const register: Register = (on, options) => {
  magpieDir = typeof options.magpieDir === 'string' ? options.magpieDir.trim().replace(/[\\/]+$/, '') : DEFAULT_MAGPIE_DIR
  language = typeof options.language === 'string' && options.language !== '' ? options.language : 'English'
  setPreferredLexicon(typeof options.lexicon === 'string' && options.lexicon !== '' ? options.lexicon.toUpperCase() : DEFAULT_LEXICON)

  on('session.start', async ($, e, next) => {
    // Each registration on its own: a refused one (a name another plugin
    // holds) must not keep the others from happening.
    await $.command
      .register({
        name: 'magpie',
        description:
          'Sim a crossword position in MAGPIE and show it in a pane, in your own words: an opening rack, a CGP, a .gcg path or URL and which turn, a lexicon, next turn, csw; no argument reopens the pane',
      })
      .catch((error: unknown) => note(`/magpie refused: ${String(error)}`))
    await $.tool
      .register({
        name: 'simulate',
        description: `Runs a MAGPIE Monte Carlo simulation of a crossword (Scrabble) position and shows the results in a pane beside the conversation, with a board picture of each play: ${SIM_SHAPE}, using WMP, RIT and WIT where the lexicon has them. Use it whenever the person asks to sim, simulate or analyze a rack or position. Takes a few seconds to a minute; one at a time. Returns the top plays by win%. For a game, at most one of turn, rack, word, letters or event picks the position; when it fits more than one, the tool lists them instead of running: ask the person which.`,
        inputSchema: {
          type: 'object',
          properties: {
            position: {
              type: 'string',
              description:
                'An opening rack (ADOPQRR, ? for a blank), a CGP string, or a path or URL of a .cgp or .gcg file; woogles.io and cross-tables.com game links work (a cross-tables viewer link\'s #13# picks the turn of its move 13). Left out: the game or position the pane shows now.',
            },
            lexicon: { type: 'string', description: 'e.g. NWL23; CSW24 unless a CGP or GCG names one' },
            after: {
              type: 'array',
              description:
                'For a rack: the moves played before it, in order. Coordinates in capitals (8G across, H8 down); a word in capitals except a blank in lowercase; a board tile as "." or in parentheses.',
              items: {
                type: 'object',
                properties: { coordinate: { type: 'string' }, word: { type: 'string' } },
                required: ['coordinate', 'word'],
              },
            },
            turn: { type: 'integer', description: "For a game: a turn number, 1 being the game's first move" },
            rack: { type: 'string', description: 'For a game: a rack the player to move held' },
            word: { type: 'string', description: 'For a game: a word played in it' },
            relation: {
              type: 'string',
              enum: ['from', 'after'],
              description: "With word: the turn it was played on (from, the default), or its player's next rack (after)",
            },
            letters: { type: 'string', description: 'For a game: letters that could be the rack or the word' },
            event: { type: 'integer', description: "For a game: MAGPIE's goto, the number of events played" },
            picture: {
              type: 'boolean',
              description:
                'Also send the person a picture of the board and the top plays, as a phone shows no pane: set it when they ask for a picture (it is sent by itself when their message came from the phone over Remote Control)',
            },
          },
        },
        isDeferred: false,
      })
      .catch((error: unknown) => note(`the simulate tool refused: ${String(error)}`))
    await $.tool
      .register({
        name: 'show',
        description:
          "Opens the MAGPIE sim pane on a finished sim's results: a file holding what `magpie ... -hr false` printed for a simulate command, optionally headed by `# lexicon <name>` and `# label <text>` lines. Leave out `file` to reopen the pane on the sim it last showed.",
        inputSchema: {
          type: 'object',
          properties: {
            file: { type: 'string', description: 'Absolute path of the results file' },
          },
        },
      })
      .catch((error: unknown) => note(`the show tool refused: ${String(error)}`))
    // Once the session is up, so the pane has a surface to open on.
    $.clock.after(SETUP_DELAY_MS, () => {
      offerSetup($).catch((error: unknown) => note(`could not offer setup: ${String(error)}`))
    })
    return next(e)
  })

  // Notes where each prompt came from, for the simulate tool: a phone's gets
  // a picture.
  on('prompt.submit', ($, e, next) => {
    lastPromptOrigin = e.origin?.kind ?? ''
    return next(e)
  }).catch(($, e, next) => next(e))

  on('command.run', { command: 'magpie' }, async ($, e) => {
    const args = e.args.trim()
    // The phone (or the web) over Remote Control draws no pane: a picture is
    // what it can show.
    const { text } = await magpieCommand($, args, e.origin?.kind === 'bridge')
    // `why` is for the mod's author: as it is.
    return { text: args === 'why' ? text : await inLanguage($, unpackTiles(text)) }
  })

  on('tool.call', { tool: 'mcp__magpie-sim__simulate' }, async ($, e) => {
    const answer = await simulateTool($, e as Record<string, unknown>)
    // A Catalan tile in brackets, as MAGPIE writes it (tiles.ts).
    return 'result' in answer ? { result: unpackTiles(answer.result) } : { deny: unpackTiles(answer.deny) }
  }).catch(($, e, next) => (next.called ? next(e) : { deny: `${PLUGIN}: the sim failed` }))

  on('tool.call', { tool: 'mcp__magpie-sim__show' }, async ($, e) => {
    const file = (e as { file?: unknown }).file
    if (typeof file === 'string' && file !== '') {
      if (!/^(?:\/|[A-Za-z]:[\\/])/.test(file)) {
        return { deny: `${PLUGIN}: give the results file as an absolute path, not ${file}` }
      }
      await update($, simFile, () => file)
      await update($, simText, () => '')
      await update($, selectedId, () => '')
      await update($, windowTop, () => 0)
    }
    let sim: Sim
    try {
      sim = await loadSim($)
    } catch (error) {
      return { deny: `${PLUGIN}: could not read the sim: ${String(error)}` }
    }
    const opened = await openPane($, await currentTitle($), false)
    note(`show: ${opened}`)
    return {
      result: [`${opened}. ${summaryLine(sim)}, ${sim.plays.length} plays. Top by win%:`, ...reportLines(sim, PLAYS_REPORTED)].join(
        '\n',
      ),
    }
  }).catch(($, e, next) => (next.called ? next(e) : { deny: `${PLUGIN}: showing the sim failed` }))

  // The wheel scrolls the table's rows: it draws only the plays that fit,
  // so there is nothing else to scroll. The selection stays where it is.
  on('ui.scroll', { requestId: PANE }, async ($, e) => {
    if (e.by !== 0) {
      await update($, windowTop, top => Math.min(Math.max(0, top + e.by), Math.max(0, lastCount - lastRoom)))
    }
    return {}
  }).catch(($, e, next) => next(e)) // a failed move lets the body scroll as usual

  on('ui.render', { component: 'Pane', requestId: PANE }, async ($, e) => {
    const where = `${e.surface}, ${e.props.bodyColumns}x${e.props.scroll.bodyRows} ${e.props.placement}`
    let drew = 'text only'
    // A failure is drawn in the pane and logged for `/magpie why`.
    try {
      const tree = await drawPane()
      note(`${where}: drew ${drew}`)
      return tree
    } catch (error) {
      note(`${where}: failed: ${String(error)}`)
      const { Text } = $.ui.resolve(e)
      return <Text color="red">{`The pane failed to draw: ${String(error)}`}</Text>
    }

    async function drawPane() {
      const { Box, Button, Text } = $.ui.resolve(e)
      const runningLabel = await read($, running)
      const error = await read($, runError)
      const status =
        runningLabel !== '' ? (
          <Text color="yellow" wrap="truncate-end">{`${runningLabel}…`}</Text>
        ) : error !== '' ? (
          <Text color="red" wrap="wrap">{`The sim failed: ${error}`}</Text>
        ) : null
      let sim: Sim
      try {
        sim = await loadSim($)
      } catch (loadError) {
        if (status !== null) {
          return status
        }
        throw loadError
      }
      const key = await read($, sortKey)
      const descending = await read($, isDescending)
      const listed = listedPlays(sim)
      const sorted = sortPlays(listed, key, descending)
      const index = selectedIndex(sorted, await read($, selectedId))
      const selected = sorted[index]
      if (selected === undefined) {
        return <Text dimColor>No plays.</Text>
      }

      let font: Font | null = null
      let fontProblem: string | null = null
      try {
        font = await loadFont($)
      } catch (fontError) {
        fontProblem = `Could not read ${FONT_FILE}: ${String(fontError)}`
      }
      // The terminal spells each play in tiles, a column of them as one
      // picture, while it and the board's fit the tree's budget (kept, so
      // drawn once); else in letters.
      const listedSlots = Math.max(1, ...listed.map(play => playTiles(play).tiles.length))
      const tiledBytes = (shownFont: Font) =>
        sourceBytes(pictureSource(shownFont, sim, selected).png) +
        sourceBytes(tilesColumnSource(shownFont, listed, selected.id, listedSlots).png)
      const isTiled = e.surface === 'terminal' && font !== null && tiledBytes(font) <= IMAGE_BUDGET
      if (e.surface === 'terminal' && font !== null) {
        drawAhead($, font, sim)
      }

      // The full table where it fits, else its main columns; the board
      // beside it where both fit, else above.
      const fullLayout = tableLayout(listed, false, isTiled, sim.kind)
      const layout = e.props.bodyColumns < fullLayout.width ? tableLayout(listed, true, isTiled, sim.kind) : fullLayout
      const isWide = e.props.bodyColumns >= BOARD_COLUMNS + 2 + layout.width
      const besideBoard = isWide ? 0 : BOARD_ROWS + 1
      const statusRows = status === null ? 0 : 1
      const room = Math.max(3, e.props.scroll.bodyRows - TABLE_CHROME_ROWS - besideBoard - statusRows)
      lastRoom = room
      lastCount = sorted.length
      // Where the wheel left the rows, whichever play is selected.
      const top = Math.min(Math.max(0, await read($, windowTop)), Math.max(0, sorted.length - room))
      const shown = sorted.slice(top, top + room)

      const alt = describePlay(selected)
      let picture = <Text dimColor>{alt}</Text>
      if (fontProblem !== null) {
        picture = <Text color="red">{fontProblem}</Text>
      } else if (font !== null) {
        if (e.surface === 'terminal') {
          isTerminalDrawing = true
          const { Image } = $.ui.resolve(e)
          picture = (
            <Image key="board" source={pictureSource(font, sim, selected)} columns={BOARD_COLUMNS} rows={BOARD_ROWS} alt={alt} />
          )
          drew = 'an Image'
        } else {
          const { Svg } = $.ui.resolve(e)
          const svg = boardSvg(font, sim.board, sim.rack, selected)
          picture = <Svg source={svg} alt={alt} />
          drew = `an Svg of ${svg.length} characters`
        }
      }

      // Each heading that sorts is a button: again to flip.
      const header = (
        <Box key="header" flexDirection="row">
          <Text bold>{'#'.padStart(RANK_WIDTH)}</Text>
          {layout.columns.map(({ column, width }) => {
            const arrow = column.sort === key ? (descending ? '▼' : '▲') : ''
            const title = ` ${pad(column.title + arrow, column, width)}`
            const sort = column.sort
            return sort === undefined ? (
              <Text bold>{title}</Text>
            ) : (
              <Button key={`sort-${sort}`} plain onPress={() => sortBy($, sort)}>
                <Text bold>{title}</Text>
              </Button>
            )
          })}
        </Box>
      )

      // Each row is a button that puts its play on the board. Tiled, the
      // rows' halves stand in two columns with the tiles between, one
      // picture down the rows that no click reaches.
      const TileImage = e.surface === 'terminal' ? $.ui.resolve(e).Image : undefined
      // The selected row on one colour, its tiles painted the same; a line
      // each, so the halves keep beside the picture's rows.
      const rowText = (text: string, isSelected: boolean) =>
        isSelected ? (
          <Text backgroundColor={SELECTED_BACKGROUND} color={SELECTED_TEXT} wrap="truncate-end">
            {text}
          </Text>
        ) : (
          <Text wrap="truncate-end">{text}</Text>
        )
      const rowButton = (play: Play, key: string, text: string) => (
        <Button key={key} plain onPress={() => selectPlay($, play.id)}>
          {rowText(text, play.id === selected.id)}
        </Button>
      )
      const tiles = layout.tiles
      const rows =
        tiles === undefined || font === null || TileImage === undefined || shown.length === 0 ? (
          shown.map(play => rowButton(play, `pick-${play.id}`, rowLine(layout, play, play.id === selected.id)))
        ) : (
          <Box key="rows" flexDirection="row">
            <Box flexDirection="column">
              {shown.map(play => rowButton(play, `pick-${play.id}`, rowParts(layout, play, play.id === selected.id).before))}
            </Box>
            {/* Keyed by its size: a picture sent again under the same id in a
                box of another size is drawn in the old one (Ghostty), so a
                new size is a new picture. */}
            <TileImage
              key={`tiles-${TILE_COLUMNS * tiles.slots}x${shown.length}`}
              source={tilesColumnSource(font, shown, selected.id, tiles.slots)}
              columns={TILE_COLUMNS * tiles.slots}
              rows={shown.length}
              alt={shown.map(playName).join(', ')}
            />
            <Box flexDirection="column">
              {shown.map(play =>
                rowButton(play, `pick-${play.id}-numbers`, rowParts(layout, play, play.id === selected.id).after),
              )}
            </Box>
          </Box>
        )

      const timing = e.surface === 'terminal' ? ` · picture ${lastPictureMs} ms` : ''
      const table = (
        <Box flexDirection="column">
          {status}
          <Text dimColor wrap="truncate-end">
            {`${summaryLine(sim)} · ${shown.length < sorted.length ? `${top + 1}-${top + shown.length} of the ` : ''}top ${sorted.length} of ${sim.plays.length}${timing}`}
          </Text>
          {header}
          {rows}
        </Box>
      )

      return isWide ? (
        <Box flexDirection="row" columnGap={2}>
          {picture}
          {table}
        </Box>
      ) : (
        <Box flexDirection="column">
          {picture}
          {table}
        </Box>
      )
    }
  })

  // The setup pane: the language and lexicon as buttons, what installing
  // does, then each step as it goes.
  on('ui.render', { component: 'Pane', requestId: SETUP_PANE }, async ($, e) => {
    const { Box, Button, Text } = $.ui.resolve(e)
    const json = await read($, setup)
    const progress = json === '' ? undefined : (JSON.parse(json) as SetupProgress)
    const choices = await setupChoices($)
    const where = await findMagpie($)
    const machine = await hostNow($)
    const installed = await isInstalled($)
    const isRunning = progress?.isRunning === true

    const chip = (key: string, label: string, isChosen: boolean, onPress: () => Promise<void>) => (
      <Button key={key} plain onPress={onPress}>
        {isChosen ? (
          <Text backgroundColor={SELECTED_BACKGROUND} color={SELECTED_TEXT}>{` ${label} `}</Text>
        ) : (
          <Text>{` ${label} `}</Text>
        )}
      </Button>
    )
    const lexica = LANGUAGES.find(candidate => candidate.name === choices.language)?.lexica ?? [choices.lexicon]
    const row = (key: string, title: string, chips: RenderChildren) => (
      <Box key={key} flexDirection="row" flexWrap="wrap">
        <Text bold>{title.padEnd(10)}</Text>
        {chips}
      </Box>
    )

    const getting = isPublished(machine) ? `downloads MAGPIE ${MAGPIE_VERSION}` : `builds MAGPIE ${MAGPIE_VERSION} from its source (about a minute)`
    const intro = installed
      ? `MAGPIE is installed in ${where.cwd}. Pick the language and lexicon you play in, then press Save.`
      : `MAGPIE runs the sims, and it is not installed yet. Pick the language and lexicon you play in, then press Install: it ${getting}, then its word lists (about 195 MB), then builds the word map of your lexicon.`
    const icon = { waiting: '·', running: '…', done: '✓', failed: '✗' } as const
    const colour = { waiting: 'gray', running: 'yellow', done: 'green', failed: 'red' } as const

    return (
      <Box flexDirection="column" rowGap={1}>
        <Text wrap="wrap">{intro}</Text>
        <Box flexDirection="column">
          {row(
            'languages',
            'Language',
            LANGUAGES.map(({ name }) => chip(`language-${name}`, name, name === choices.language, () => pickLanguage($, name))),
          )}
          {row(
            'lexica',
            'Lexicon',
            lexica.map(name => chip(`lexicon-${name}`, name, name === choices.lexicon, () => pickLexicon($, name))),
          )}
          <Text dimColor wrap="truncate-end">{`${'Folder'.padEnd(10)}${where.cwd ?? ''}  (change it in /config, ${PLUGIN})`}</Text>
        </Box>
        {isRunning ? null : (
          <Box flexDirection="row" columnGap={2}>
            <Button key="install" onPress={() => void startSetup($)}>
              {installed ? 'Save' : 'Install'}
            </Button>
            {installed ? null : (
              <Button key="decline" onPress={() => declineSetup($)}>
                Not now
              </Button>
            )}
          </Box>
        )}
        {progress === undefined ? null : (
          <Box flexDirection="column">
            {progress.steps.map(step => (
              <Text key={`step-${step.key}`} wrap="truncate-end">
                <Text color={colour[step.state]}>{`${icon[step.state]} `}</Text>
                {step.label}
                <Text dimColor>{step.detail === '' ? '' : `  ${step.detail}`}</Text>
              </Text>
            ))}
            {progress.problem === '' ? null : (
              <Text color="red" wrap="wrap">
                {progress.problem}
              </Text>
            )}
            {progress.remedy === 'tools' ? (
              <Button key="tools" onPress={() => getAppleTools($)}>
                Get the tools
              </Button>
            ) : null}
            {progress.isDone ? (
              <Text color="green" wrap="wrap">
                {`MAGPIE is ready, in ${choices.lexicon}. Try /magpie AEINRST, or ask Claude to sim a position.`}
              </Text>
            ) : null}
            {progress.saved === undefined || progress.saved === '' ? null : <Text wrap="wrap">{progress.saved}</Text>}
          </Box>
        )}
      </Box>
    )
  })
}

