import type { EngineInterface } from 'claude-code'

// Installing MAGPIE for the mod: its executable (downloaded where one is
// published for the computer, else built from its source), then its data,
// which MAGPIE fetches itself, then the word map of the person's lexicon.

/** The MAGPIE release the mod installs. */
export const MAGPIE_VERSION = '0.1.3'
const RELEASES = 'https://github.com/jvc56/MAGPIE/releases/download'
const SOURCE = `https://github.com/jvc56/MAGPIE/archive/refs/tags/v${MAGPIE_VERSION}.tar.gz`
// The folder the source tarball unpacks to.
const SOURCE_FOLDER = `MAGPIE-${MAGPIE_VERSION}`

export type Os = 'macos' | 'linux' | 'windows'
export type Arch = 'x64' | 'arm64'
export type Host = { os: Os; arch: Arch }

// The executables published for MAGPIE_VERSION, with the SHA-256 published
// beside each. A computer with none builds MAGPIE from its source.
const EXECUTABLES: Partial<Record<`${Os}-${Arch}`, { file: string; sha256: string }>> = {
  'windows-x64': {
    file: `magpie-${MAGPIE_VERSION}-windows-x64.exe`,
    sha256: '2d493ebd0f76b435bf26679d8e4c40d426ebf6906e596b4b69b47d1279b84ee6',
  },
  'windows-arm64': {
    file: `magpie-${MAGPIE_VERSION}-windows-arm64.exe`,
    sha256: '5aae3aa75c4ac982553e1f44fc5b6312aea444f35b54075f5ebf8761f5cd9610',
  },
}

/** Whether an executable is published for the computer; if not, MAGPIE is
 * built from its source there. */
export function isPublished(host: Host): boolean {
  return EXECUTABLES[`${host.os}-${host.arch}`] !== undefined
}

/** The languages MAGPIE plays in, each by its own name and its English one,
 * with its lexicons (the ones MAGPIE's data holds), newest and most played
 * first. */
export const LANGUAGES: readonly { name: string; english: string; lexica: readonly string[] }[] = [
  {
    name: 'English',
    english: 'English',
    lexica: ['CSW24', 'NWL23', 'CSW21', 'NWL20', 'TWL14', 'CSW15', 'TWL06', 'CSW12', 'CSW07', 'TWL98', 'OSWI', 'OSW4', 'OSW3', 'OSW2', 'OSW1'],
  },
  { name: 'Français', english: 'French', lexica: ['FRA20'] },
  { name: 'Deutsch', english: 'German', lexica: ['RD29'] },
  { name: 'Nederlands', english: 'Dutch', lexica: ['DSW25'] },
  { name: 'Català', english: 'Catalan', lexica: ['DISC2'] },
  { name: 'Polski', english: 'Polish', lexica: ['OSPS49'] },
]

/** A language's English name, English for one not listed. */
export function englishNameOf(language: string): string {
  return LANGUAGES.find(candidate => candidate.name === language)?.english ?? 'English'
}

/** The language a lexicon is in, English for one not listed. */
export function languageOf(lexicon: string): string {
  return LANGUAGES.find(language => language.lexica.includes(lexicon.toUpperCase()))?.name ?? 'English'
}

/** A language's first lexicon, CSW24 for one not listed. */
export function firstLexicon(language: string): string {
  return LANGUAGES.find(candidate => candidate.name === language)?.lexica[0] ?? 'CSW24'
}

/** Whether MAGPIE builds a word map for the lexicon: Polish has none. */
export function hasWordmap(lexicon: string): boolean {
  return !/^OSPS/i.test(lexicon)
}

/** The computer the session runs on. */
export async function hostOf($: EngineInterface): Promise<Host> {
  if ((await $.env.get('OS')) === 'Windows_NT') {
    // A 32-bit process on 64-bit Windows sees the machine's in the first.
    const arch = (await $.env.get('PROCESSOR_ARCHITEW6432')) ?? (await $.env.get('PROCESSOR_ARCHITECTURE')) ?? ''
    return { os: 'windows', arch: /arm64/i.test(arch) ? 'arm64' : 'x64' }
  }
  const { stdout } = await $.process.run(['uname', '-sm'])
  const [kernel = '', machine = ''] = stdout.trim().split(/\s+/)
  return { os: kernel === 'Darwin' ? 'macos' : 'linux', arch: /arm64|aarch64/i.test(machine) ? 'arm64' : 'x64' }
}

/** The person's home folder: HOME, or on Windows USERPROFILE. */
export async function homeOf($: EngineInterface): Promise<string> {
  return (await $.env.get('HOME')) ?? (await $.env.get('USERPROFILE')) ?? ''
}

/** Where the mod installs MAGPIE unless told otherwise: on Windows the folder
 * MAGPIE itself looks in (%LOCALAPPDATA%\MAGPIE), elsewhere ~/.magpie. */
export async function defaultMagpieDir($: EngineInterface, host: Host): Promise<string> {
  const local = host.os === 'windows' ? await $.env.get('LOCALAPPDATA') : undefined
  return local === undefined || local === '' ? `${await homeOf($)}/.magpie` : `${local}\\MAGPIE`
}

/** The executable in a MAGPIE folder. */
export function executableIn(dir: string, host: Host): string {
  return `${dir}/bin/magpie${host.os === 'windows' ? '.exe' : ''}`
}

/** A step of the install, as the setup pane lists it. */
export type SetupStep = {
  key: 'magpie' | 'data' | 'wordmap'
  label: string
  state: 'waiting' | 'running' | 'done' | 'failed'
  detail: string
}

/** How the install goes: its steps, and why it stopped, with what the pane
 * offers to do about it (`tools`: install Apple's command-line tools); once
 * done, how saving the choices went. */
export type SetupProgress = {
  steps: SetupStep[]
  problem: string
  remedy?: 'tools'
  isRunning: boolean
  isDone: boolean
  saved?: string
}

export type SetupPlan = { host: Host; dir: string; lexicon: string; threads: number }

/** A stop the person can do something about: what, and what the pane offers. */
class SetupProblem extends Error {
  readonly remedy?: 'tools'

  constructor(message: string, remedy?: 'tools') {
    super(message)
    this.remedy = remedy
  }
}

export function setupSteps(plan: SetupPlan): SetupStep[] {
  return [
    { key: 'magpie', label: `MAGPIE ${MAGPIE_VERSION}`, state: 'waiting', detail: '' },
    { key: 'data', label: 'Word lists and strategy files (about 195 MB)', state: 'waiting', detail: '' },
    { key: 'wordmap', label: `The ${plan.lexicon} word map`, state: 'waiting', detail: '' },
  ]
}

/** Installs what the plan's folder lacks, one step after another, telling
 * `report` each change. Resolves whether it all went. */
export async function installMagpie(
  $: EngineInterface,
  plan: SetupPlan,
  report: (progress: SetupProgress) => Promise<void>,
): Promise<boolean> {
  const progress: SetupProgress = { steps: setupSteps(plan), problem: '', isRunning: true, isDone: false }
  const tell = () => report({ ...progress, steps: progress.steps.map(step => ({ ...step })) })
  let current: SetupStep | undefined
  const step = async (key: SetupStep['key'], work: (say: (detail: string) => Promise<void>) => Promise<void>) => {
    current = progress.steps.find(candidate => candidate.key === key)
    if (current === undefined) {
      return
    }
    const shown = current
    shown.state = 'running'
    await tell()
    await work(async detail => {
      shown.detail = detail
      await tell()
    })
    shown.state = 'done'
    await tell()
  }
  try {
    await step('magpie', say => getExecutable($, plan, say))
    await step('data', say => getData($, plan, say))
    await step('wordmap', say => buildWordmap($, plan, say))
    progress.isDone = true
  } catch (error) {
    if (current !== undefined) {
      current.state = 'failed'
    }
    progress.problem = error instanceof Error ? error.message : String(error)
    if (error instanceof SetupProblem && error.remedy !== undefined) {
      progress.remedy = error.remedy
    }
  }
  progress.isRunning = false
  await tell()
  return progress.isDone
}

// A command that must succeed; its error output is the reason when not.
async function mustRun($: EngineInterface, argv: readonly string[], what: string, cwd?: string): Promise<string> {
  const result = await $.process.run(argv, { cwd, timeoutMs: 600_000 }).catch((error: unknown) => {
    throw new Error(`could not ${what}: ${error instanceof Error ? error.message : String(error)}`)
  })
  if (result.exitCode !== 0) {
    const said = `${result.stderr}\n${result.stdout}`.trim().split('\n').slice(-3).join(' ')
    throw new Error(`could not ${what}${said === '' ? '' : `: ${said}`}`)
  }
  return result.stdout
}

/** A path as Windows' own commands take it. */
export const windowsPath = (path: string) => path.replaceAll('/', '\\')

async function sha256Of($: EngineInterface, host: Host, path: string): Promise<string> {
  if (host.os === 'windows') {
    // certutil prints the hash on a line of its own, spaced on old Windows.
    const said = await mustRun($, ['certutil', '-hashfile', windowsPath(path), 'SHA256'], 'check the download')
    return (said.split('\n').map(line => line.replace(/\s/g, '')).find(line => /^[0-9a-f]{64}$/i.test(line)) ?? '').toLowerCase()
  }
  const said = await mustRun($, host.os === 'macos' ? ['shasum', '-a', '256', path] : ['sha256sum', path], 'check the download')
  return said.trim().split(/\s+/)[0]?.toLowerCase() ?? ''
}

async function remove($: EngineInterface, host: Host, path: string) {
  await $.process
    .run(host.os === 'windows' ? ['cmd', '/d', '/c', 'del', '/f', '/q', windowsPath(path)] : ['rm', '-f', path])
    .catch(() => undefined)
}

async function getExecutable($: EngineInterface, plan: SetupPlan, say: (detail: string) => Promise<void>) {
  const executable = executableIn(plan.dir, plan.host)
  if (await $.fs.exists(executable)) {
    await say(`already in ${plan.dir}`)
    return
  }
  const published = EXECUTABLES[`${plan.host.os}-${plan.host.arch}`]
  if (published === undefined) {
    await buildFromSource($, plan, say)
    return
  }
  await say(`downloading ${published.file}`)
  await mustRun($, ['curl', '-fsSL', '--create-dirs', '-o', executable, `${RELEASES}/v${MAGPIE_VERSION}/${published.file}`], 'download MAGPIE')
  const sha256 = await sha256Of($, plan.host, executable)
  if (sha256 !== published.sha256) {
    await remove($, plan.host, executable)
    throw new Error(`the download of ${published.file} is not the one published (SHA-256 ${sha256 || 'unknown'}), so it was deleted`)
  }
  await say(`downloaded to ${plan.dir}`)
}

// What building needs, said plainly when it is missing.
async function checkTools($: EngineInterface, host: Host) {
  if (host.os === 'macos') {
    const tools = await $.process.run(['xcode-select', '-p']).catch(() => undefined)
    if (tools?.exitCode !== 0) {
      throw new SetupProblem(
        "No MAGPIE is published for Macs yet, so it is built here, which needs Apple's command-line tools. Press Get the tools, finish Apple's installer, then press Install again.",
        'tools',
      )
    }
    return
  }
  const found = await $.process
    .run(['sh', '-c', 'command -v make && command -v cc && command -v curl && command -v tar'])
    .catch(() => undefined)
  if (found?.exitCode !== 0) {
    throw new SetupProblem(
      'No MAGPIE is published for Linux yet, so it is built here, which needs make, a C compiler, curl and tar. On Debian or Ubuntu: sudo apt install build-essential curl. On Fedora: sudo dnf install make gcc curl tar. Then press Install again.',
    )
  }
}

// One `make` of MAGPIE, telling how many files it has compiled. Resolves
// whether it built, and the last of what it said.
async function make(
  $: EngineInterface,
  source: string,
  targets: readonly string[],
  say: (detail: string) => Promise<void>,
): Promise<{ isBuilt: boolean; said: string }> {
  let said = ''
  let compiled = 0
  const stream = $.process.spawn({ argv: ['make', ...targets], cwd: source })
  for await (const { text } of stream) {
    said = `${said}${text}`.slice(-4000)
    const count = text.split('\n').filter(line => / -c /.test(line)).length
    if (count > 0) {
      compiled += count
      await say(`building: ${compiled} files compiled`)
    }
    if (/-o bin\/magpie\b/.test(text)) {
      await say(`building: ${compiled} files compiled, now linking (the slow part)`)
    }
  }
  const { code } = await stream.result
  return { isBuilt: code === 0, said }
}

async function buildFromSource($: EngineInterface, plan: SetupPlan, say: (detail: string) => Promise<void>) {
  await checkTools($, plan.host)
  const work = `${plan.dir}/build`
  const tarball = `${work}/magpie-${MAGPIE_VERSION}.tar.gz`
  const source = `${work}/${SOURCE_FOLDER}`
  await say('downloading the source')
  await mustRun($, ['curl', '-fsSL', '--create-dirs', '-o', tarball, SOURCE], 'download the source')
  await mustRun($, ['tar', '-xzf', tarball, '-C', work], 'unpack the source')
  await say('building (about a minute)')
  // The build for this very computer, or failing that the portable one the
  // published executables are.
  let build = await make($, source, ['magpie', 'BUILD=no_pgo_release'], say)
  if (!build.isBuilt) {
    await say('building again, the portable way')
    const march = plan.host.arch === 'arm64' ? 'armv8-a' : 'nehalem'
    build = await make($, source, ['magpie', 'BUILD=portable_release', `PORTABLE_MARCH=${march}`], say)
  }
  if (!build.isBuilt) {
    const why = build.said.trim().split('\n').filter(line => /error/i.test(line)).slice(-2).join(' ')
    throw new Error(`MAGPIE did not build${why === '' ? '' : `: ${why}`}`)
  }
  await mustRun($, ['mkdir', '-p', `${plan.dir}/bin`], 'make the bin folder')
  await mustRun($, ['cp', `${source}/bin/magpie`, executableIn(plan.dir, plan.host)], 'put MAGPIE in place')
  await $.process.run(['rm', '-rf', work]).catch(() => undefined)
  await say(`built in ${plan.dir}`)
}

// MAGPIE's own fetch: every language's word lists, each chunk checked
// against its SHA-256, unpacked file by file.
async function getData($: EngineInterface, plan: SetupPlan, say: (detail: string) => Promise<void>) {
  const kwg = `${plan.dir}/data/lexica/${plan.lexicon}.kwg`
  if (await $.fs.exists(kwg)) {
    await say('already there')
    return
  }
  let said = ''
  const stream = $.process.spawn({ argv: [executableIn(plan.dir, plan.host), 'data', 'fetch'], cwd: plan.dir })
  for await (const { text } of stream) {
    said = `${said}${text}`.slice(-4000)
    const line = said.replaceAll('\r', '\n').trim().split('\n').at(-1)?.trim()
    if (line !== undefined && line !== '') {
      await say(line)
    }
  }
  const { code } = await stream.result
  if (code !== 0) {
    const why = said.trim().split('\n').slice(-2).join(' ')
    throw new Error(`the data did not download (exit ${code})${why === '' ? '' : `: ${why}`}`)
  }
  if (!(await $.fs.exists(kwg))) {
    throw new Error(`the data downloaded, but holds no ${plan.lexicon}`)
  }
  await say('downloaded')
}

// MAGPIE builds a lexicon's word map the first time it loads it; loading it
// here spares the first sim the wait.
async function buildWordmap($: EngineInterface, plan: SetupPlan, say: (detail: string) => Promise<void>) {
  if (!hasWordmap(plan.lexicon)) {
    await say('none for Polish')
    return
  }
  const wordmap = `${plan.dir}/data/lexica/${plan.lexicon}.wmp`
  if (await $.fs.exists(wordmap)) {
    await say('already built')
    return
  }
  await say('building (a few seconds)')
  const args = ['setoptions', '-lex', plan.lexicon, '-wmp', 'true', '-threads', String(plan.threads)]
  await mustRun($, [executableIn(plan.dir, plan.host), ...args], `build the ${plan.lexicon} word map`, plan.dir)
  if (!(await $.fs.exists(wordmap))) {
    throw new Error(`MAGPIE did not build the ${plan.lexicon} word map`)
  }
  await say('built')
}

files.hooks/sim.ts:
// Reads a sim as MAGPIE prints it with `-hr false`: a line per simmed play,
// then a summary. The columns are src/str/sim_string.c's UCGI ones: rank,
// move, leave, score, Ig, Wp, WpSE, Eq, EqSE, StEq, It, then each ply's
// score mean, score stdev and bingo%. Lines starting `# lexicon` name the
// lexicon, which the output leaves out.

import { BOARD_DIM, COLUMN_LETTERS } from './layout'
import { packTiles, unpackTiles } from './tiles'

export type PlyStats = { score: number; stdev: number; bingoPct: number }

export type Play = {
  /** Where the sim ranked it: by win%. */
  rank: number
  /** As the sim lists it: `8F DROP`, `exch Q`, `pass`. */
  id: string
  kind: 'place' | 'exchange' | 'pass'
  /** The word, `.` for a tile already on the board and lowercase for a
   * blank; for an exchange the tiles thrown back; empty for a pass. */
  tiles: string
  row: number
  col: number
  isDown: boolean
  leave: string
  score: number
  winPct: number
  winSe: number
  equity: number
  equitySe: number
  staticEquity: number
  iterations: number
  plies: PlyStats[]
  /** An endgame's: the final spread for the player to move, what the line
   * nets them, and the rest of the line (a going-out play's end points). */
  result?: number
  net?: number
  line?: string
}

export type Sim = {
  /** A Monte Carlo sim, or an endgame solved (the bag empty). */
  kind: 'sim' | 'endgame'
  /** Sorted, blanks last, as MAGPIE writes a rack. */
  rack: string
  lexicon: string
  /** What the person named: a rack, a file, a URL. */
  label: string
  /** The position's rows, `.` empty and lowercase a blank; null when the
   * output printed no board (an opening rack). */
  board: string[] | null
  plays: Play[]
  /** A sim's plies, or the endgame solver's depth. */
  plies: number
  iterations: number
  seconds: number
  status: string
}

const PLAY_LINE = /^\s*(\d+):\s+(.*)$/
// `shgame`'s header or top border, whichever holds the on-turn marker: a
// name, a rack and a score.
const ON_TURN = /^\s+(?:A B C D E F G H I J K L M N O|-{30})\s+>\s+(.+?)\s{2,}([\p{L}?]{1,7})\s+-?\d+\s*$/mu
const ENDGAME_HEADER = /^Endgame \(depth: (\d+), time: ([\d.]+)s, status: ([^)]*)\)/
// An endgame row's first move: square, word, score, and a going-out play's
// end points in parentheses.
const ENDGAME_MOVE = /^(pass|\S+\s+\S+)\s+(-?\d+)(?:\s+(\(.*\)))?$/
// The Ig column: X for a play the threshold found too close to the best.
const IGNORED_MARKS = new Set(['-', 'X'])
// Wp, WpSE, Eq, EqSE, StEq, It.
const STAT_COLUMNS = 6
const PLY_COLUMNS = 3

function numberAt(tokens: readonly string[], at: number, line: string): number {
  const value = Number(tokens[at])
  if (tokens[at] === undefined || Number.isNaN(value)) {
    throw new Error(`no number in column ${at + 1} of "${line.trim()}"`)
  }
  return value
}

// `8F` is across, row first; `H8` is down, column first.
function parseCoordinates(text: string): { row: number; col: number; isDown: boolean } {
  const across = /^(\d+)([A-Z])$/.exec(text)
  const down = /^([A-Z])(\d+)$/.exec(text)
  const [rowText, colText, isDown] =
    across !== null ? [across[1], across[2], false] : down !== null ? [down[2], down[1], true] : []
  const row = Number(rowText) - 1
  const col = COLUMN_LETTERS.indexOf(colText ?? '')
  if (isDown === undefined || row < 0 || row >= BOARD_DIM || col < 0) {
    throw new Error(`no square at ${text}`)
  }
  return { row, col, isDown }
}

// MAGPIE writes the tiles a play goes through in parentheses, `(S)ILVERED`;
// a `.` stands for each, as in a GCG.
function boardTilesAsDots(word: string): string {
  return word.replace(/\(([^)]*)\)/g, (_, onBoard: string) => '.'.repeat(onBoard.length))
}

export function parsePlayLine(line: string): Play | null {
  const match = PLAY_LINE.exec(line)
  if (match === null) {
    return null
  }
  const tokens = (match[2] ?? '').trim().split(/\s+/)
  let at = 0
  let play: Pick<Play, 'id' | 'kind' | 'tiles' | 'row' | 'col' | 'isDown'>
  if (tokens[0] === '(exch') {
    const tiles = (tokens[1] ?? '').replace(/\)$/, '')
    play = { id: `exch ${tiles}`, kind: 'exchange', tiles, row: 0, col: 0, isDown: false }
    at = 2
  } else if (tokens[0] === 'pass') {
    play = { id: 'pass', kind: 'pass', tiles: '', row: 0, col: 0, isDown: false }
    at = 1
  } else {
    const word = tokens[1] ?? ''
    play = { id: `${tokens[0]} ${word}`, kind: 'place', tiles: boardTilesAsDots(word), ...parseCoordinates(tokens[0] ?? '') }
    at = 2
  }
  // A play that spends the whole rack leaves an empty leave cell, which the
  // split drops: the score is whatever stands before the Ig mark.
  const ignoredAt = tokens.findIndex((token, index) => index > at && IGNORED_MARKS.has(token))
  if (ignoredAt < 0) {
    throw new Error(`no Ig column in "${line.trim()}"`)
  }
  const leave = ignoredAt - at === 2 ? (tokens[at] ?? '') : ''
  const stats = ignoredAt + 1
  const plyCount = Math.floor((tokens.length - stats - STAT_COLUMNS) / PLY_COLUMNS)
  const plies: PlyStats[] = []
  for (let ply = 0; ply < plyCount; ply++) {
    const first = stats + STAT_COLUMNS + ply * PLY_COLUMNS
    plies.push({
      score: numberAt(tokens, first, line),
      stdev: numberAt(tokens, first + 1, line),
      bingoPct: numberAt(tokens, first + 2, line),
    })
  }
  return {
    ...play,
    rank: Number(match[1]),
    leave,
    score: numberAt(tokens, ignoredAt - 1, line),
    winPct: numberAt(tokens, stats, line),
    winSe: numberAt(tokens, stats + 1, line),
    equity: numberAt(tokens, stats + 2, line),
    equitySe: numberAt(tokens, stats + 3, line),
    staticEquity: numberAt(tokens, stats + 4, line),
    iterations: numberAt(tokens, stats + 5, line),
    plies,
  }
}

/** The tiles a play takes from the rack: a blank as `?`. */
export function spentTiles(play: Play): string {
  if (play.kind === 'exchange') {
    return play.tiles
  }
  return [...play.tiles]
    .filter(letter => letter !== '.')
    .map(letter => (letter === letter.toLowerCase() ? '?' : letter))
    .join('')
}

function sortRack(tiles: string): string {
  // `?` sorts before the letters in ASCII; MAGPIE writes blanks last.
  return [...tiles].sort((a, b) => (a === '?' ? 1 : b === '?' ? -1 : a.localeCompare(b))).join('')
}

// A row of `shgame`'s ASCII board (-pretty false): its number, a bar, then
// two characters a square, the first a letter or a premium mark.
const BOARD_ROW = new RegExp(`^\\s?(\\d{1,2})\\|(.{${BOARD_DIM * 2}})\\|`)

/** The board rows `shgame` printed, the last board printed winning. */
export function parseBoard(lines: readonly string[]): string[] | null {
  let board: string[] | null = null
  for (const line of lines) {
    const match = BOARD_ROW.exec(line)
    if (match === null) {
      continue
    }
    const row = Number(match[1]) - 1
    if (row === 0) {
      board = []
    }
    if (board !== null && row === board.length) {
      const squares = match[2] ?? ''
      board.push(
        Array.from({ length: BOARD_DIM }, (_, col) => {
          const char = squares[col * 2] ?? ' '
          return /\p{L}/u.test(char) ? char : '.'
        }).join(''),
      )
    }
  }
  return board?.length === BOARD_DIM ? board : null
}

/** The rack the player to move holds, as the last game printed shows it. */
function onTurnRack(text: string): string | undefined {
  const racks = [...text.matchAll(new RegExp(ON_TURN.source, 'gmu'))]
  return racks[racks.length - 1]?.[2]
}

/** An endgame as MAGPIE's solver prints it: a header with its depth and
 * time, then a row per first move, its columns where the headings start:
 * the move (and a going-out play's end points), V (what the line nets), S
 * (the final spread), then each later turn of the line. */
function parseEndgame(lines: readonly string[], at: number, rack: string): Pick<Sim, 'plays' | 'plies' | 'seconds' | 'status'> {
  const header = ENDGAME_HEADER.exec(lines[at] ?? '')
  const headings = lines[at + 1] ?? ''
  const starts = [...headings.matchAll(/Play|V|S|Turn \d+/g)].map(match => match.index)
  const [, netAt = 0, resultAt = 0, ...turnsAt] = starts
  const plays: Play[] = []
  for (let index = at + 2; index < lines.length && (lines[index] ?? '').trim() !== ''; index++) {
    const row = lines[index] ?? ''
    const cell = (from: number, to: number | undefined) => row.slice(from, to).trim()
    const move = ENDGAME_MOVE.exec(cell(0, netAt))
    if (move === null) {
      continue
    }
    const what = move[1] ?? ''
    const isPass = what === 'pass'
    const [square = '', word = ''] = what.split(/\s+/)
    const tiles = isPass ? '' : boardTilesAsDots(word)
    const later = turnsAt.map((from, turn) => cell(from, turnsAt[turn + 1])).filter(turn => turn !== '')
    const placed = isPass ? { row: 0, col: 0, isDown: false } : parseCoordinates(square)
    const play: Play = {
      rank: plays.length + 1,
      id: isPass ? 'pass' : `${square} ${word}`,
      kind: isPass ? 'pass' : 'place',
      tiles,
      ...placed,
      leave: '',
      score: Number(move[2]),
      winPct: 0,
      winSe: 0,
      equity: 0,
      equitySe: 0,
      staticEquity: 0,
      iterations: 0,
      plies: [],
      result: Number(cell(resultAt, turnsAt[0])),
      net: Number(cell(netAt, resultAt)),
      line: [move[3] ?? '', ...later].filter(part => part !== '').join(' · '),
    }
    play.leave = leaveAfter(rack, play)
    plays.push(play)
  }
  return {
    plays,
    plies: Number(header?.[1] ?? 0),
    seconds: Number(header?.[2] ?? 0),
    status: header?.[3] ?? '',
  }
}

// What stays on the rack once the play's tiles leave it.
function leaveAfter(rack: string, play: Play): string {
  const ghosts = rackGhosts(rack, play)
  return [...rack].filter((_, index) => ghosts[index] !== true).join('')
}

export function parseSim(printed: string): Sim {
  // A Catalan tile is one letter here (tiles.ts), as MAGPIE's own output
  // has it by now; a file's still has it in brackets.
  const text = packTiles(printed)
  const lines = text.split('\n')
  const endgameAt = lines.findIndex(line => ENDGAME_HEADER.test(line))
  if (endgameAt >= 0) {
    const rack = sortRack(onTurnRack(text) ?? '')
    const endgame = parseEndgame(lines, endgameAt, rack)
    if (endgame.plays.length === 0) {
      throw new Error('the endgame solver printed no plays')
    }
    return {
      kind: 'endgame',
      rack,
      lexicon: /^#\s*lexicon\s+(\S+)/m.exec(text)?.[1] ?? '',
      label: /^#\s*label\s+(.*?)\s*$/m.exec(text)?.[1] ?? '',
      board: parseBoard(lines),
      iterations: 0,
      ...endgame,
    }
  }
  // The sim's table is the run of play lines just before `Showing N of M
  // plays`; a move list printed earlier (by `shgame`) is another run.
  let plays: Play[] = []
  let run: Play[] = []
  let lastRun: Play[] = []
  let lexicon = ''
  let label = ''
  let plies = 0
  let iterations = 0
  let seconds = 0
  let status = ''
  for (const line of lines) {
    const header = /^#\s*(lexicon|label)\s+(.*?)\s*$/.exec(line)
    const shownPlays = /^Showing \d+ of \d+ plays/.test(line)
    const shownPlies = /^Showing \d+ of (\d+) plies/.exec(line)
    const summary = /^(Iters|Time|Status):\s+(.*?)\s*$/.exec(line)
    const play = header === null ? parsePlayLine(line) : null
    if (play !== null) {
      run.push(play)
      continue
    }
    if (run.length > 0) {
      lastRun = run
      run = []
    }
    if (header !== null) {
      if (header[1] === 'lexicon') {
        lexicon = header[2] ?? ''
      } else {
        label = header[2] ?? ''
      }
    } else if (shownPlays) {
      plays = lastRun
    } else if (shownPlies !== null) {
      plies = Number(shownPlies[1])
    } else if (summary !== null) {
      const value = summary[2] ?? ''
      if (summary[1] === 'Iters') {
        iterations = Number(value)
      } else if (summary[1] === 'Time') {
        seconds = Number.parseFloat(value)
      } else {
        status = value
      }
    }
  }
  const first = plays[0]
  if (first === undefined) {
    throw new Error('the output holds no simmed plays: was it printed with -hr false?')
  }
  return {
    kind: 'sim',
    // The player to move's, as shgame printed it; else every play's spent
    // tiles and leave make it, the first's as well as any.
    rack: sortRack(onTurnRack(text) ?? spentTiles(first) + first.leave),
    lexicon,
    label,
    board: parseBoard(lines),
    plays,
    plies: plies || first.plies.length,
    iterations,
    seconds,
    status,
  }
}

/** Where each placed tile lands, the board's own tiles skipped. */
export function placedTiles(play: Play): { row: number; col: number; letter: string }[] {
  if (play.kind !== 'place') {
    return []
  }
  return [...play.tiles].flatMap((letter, offset) =>
    letter === '.'
      ? []
      : [{ row: play.row + (play.isDown ? offset : 0), col: play.col + (play.isDown ? 0 : offset), letter }],
  )
}

// Which rack tiles the play spends, in rack order: the first unspent tile of
// each letter it takes, as the TUI ghosts them.
export function rackGhosts(rack: string, play: Play): boolean[] {
  const needed = [...spentTiles(play)]
  return [...rack].map(letter => {
    const at = needed.indexOf(letter)
    if (at < 0) {
      return false
    }
    needed.splice(at, 1)
    return true
  })
}

/** What the picture shows, in words, for the surfaces that cannot see it. */
export function describePlay(play: Play): string {
  if (play.kind === 'exchange') {
    return unpackTiles(`Exchange ${play.tiles}, keeping ${play.leave || 'nothing'}`)
  }
  if (play.kind === 'pass') {
    return 'Pass'
  }
  return unpackTiles(`The board with ${play.id} placed, ${play.score} points`)
}

/** A play as people write it: `8F DROP`, an exchange `-EO`, `pass`. */
export function playName(play: Play): string {
  return play.kind === 'exchange' ? `-${play.tiles}` : play.id
}

/** A play as the table spells it: its square (`-` before an exchange's
 * tiles, `pass`) and its tiles, the board's own (in parentheses) marked. */
export function playTiles(play: Play): { label: string; tiles: { letter: string; isThrough: boolean }[] } {
  if (play.kind === 'exchange') {
    return { label: '-', tiles: [...play.tiles].map(letter => ({ letter, isThrough: false })) }
  }
  if (play.kind === 'pass') {
    return { label: 'pass', tiles: [] }
  }
  const [label = '', word = ''] = play.id.split(' ')
  const tiles: { letter: string; isThrough: boolean }[] = []
  let isThrough = false
  for (const char of word) {
    if (char === '(' || char === ')') {
      isThrough = char === '('
    } else {
      tiles.push({ letter: char, isThrough })
    }
  }
  return { label, tiles }
}

/** An endgame's result as players write it: W+20 a win by 20, L-10 a loss
 * by 10, T=0 a tie. */
export function resultText(result: number | undefined): string {
  if (result === undefined) {
    return ''
  }
  return result > 0 ? `W+${result}` : result < 0 ? `L${result}` : 'T=0'
}

/** The latest whole results table in a sim's output so far, as parseSim
 * reads it: MAGPIE, asked to print as it goes (`-pfrequency`), prints the
 * board, then a table each so often, each ending with its `Nps:` line; the
 * board goes before the latest. `count` is how many tables have ended;
 * undefined before the first has. */
export function latestTable(output: string): { text: string; count: number } | undefined {
  const ends = [...output.matchAll(/^Nps:.*$/gm)].map(match => match.index + match[0].length)
  const end = ends[ends.length - 1]
  if (end === undefined) {
    return undefined
  }
  const start = ends[ends.length - 2] ?? 0
  const table = output.slice(start, end)
  if (start === 0) {
    return { text: table, count: ends.length }
  }
  const firstRow = output.search(/^\d+:\s/m)
  return { text: `${firstRow < 0 ? '' : output.slice(0, firstRow)}${table.replace(/^\n/, '')}`, count: ends.length }
}

