export const PREVIEW_BG: Rgb = [
  (TILE_FG[0] + BACKGROUND[0]) / 2,
  (TILE_FG[1] + BACKGROUND[1]) / 2,
  (TILE_FG[2] + BACKGROUND[2]) / 2,
]
